    ).pipe(Effect.provide(flagsLayer));

    const environment = yield* Cloudflare.WorkerEnvironment;

    // SAFETY: these are the native runtime bindings declared above. Alchemy types the environment as a dictionary it fills in at runtime, so this is the one boundary cast.
    // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- Alchemy types the Worker environment as a dictionary, so the declared bindings need one boundary cast.
    const bindings = environment as RateLimitBindings & {
      readonly CODE_SANDBOX: WorkerLoaderBinding;
    };

    const loader = bindings.CODE_SANDBOX;

    const rateLimits = rateLimitsFrom({
      API_PER_IP: bindings.API_PER_IP,
      EXECUTE_GLOBAL: bindings.EXECUTE_GLOBAL,
      EXECUTE_PER_IP: bindings.EXECUTE_PER_IP,
      INTEREST_PER_IP: bindings.INTEREST_PER_IP,
    });

    const interestServices = Option.isNone(interestTokenSecret)
      ? undefined
      : yield* Layer.build(
          Layer.mergeAll(
            interestDirectory,
            InterestTokens.layer(interestTokenSecret.value),
            InterestMode.layer(interestMode),
            subscriberDeliveryLayer({
              agentIntake: {
                credential: drovrAgentIntakeCredential,
                url: drovrIntakeUrl,
              },
              confirm: {
                base: drovrApiBase,
                credential: drovrIntakeCredential,
              },
              intake: {
                credential: drovrIntakeCredential,
                url: drovrIntakeUrl,
              },
              intakeTimeout: drovrIntakeTimeoutSeconds.pipe(
                Option.map(Duration.seconds),
                Option.getOrUndefined
              ),
            })
          )
        );

    const interest =
      interestServices === undefined
        ? undefined
        : {
            operatorToken: interestOperatorToken.pipe(
              Option.map(Redacted.value),
              Option.getOrUndefined
            ),
            services: interestServices,
          };

    const joinServices =
      agentSignup !== undefined && interestServices !== undefined
        ? yield* Layer.build(
            agentSignupLayer(agentSignup, interestServices).pipe(
              Layer.provide(deliveryDeadlineLayer(joinDeliveryDeadlineSeconds))
            )
          )
        : undefined;

    yield* scheduleIntakeSweep(agentSignup, joinServices);

    const applications =
      agentSignup?.applications === undefined || joinServices === undefined
        ? undefined
        : yield* IntakeApplications.pipe(
            Effect.provide(
              agentSignup.applications.pipe(
                Layer.provide(Layer.succeedContext(joinServices))
              )
            )
          );

    const erasure =
      joinServices === undefined
        ? undefined
        : yield* IntakeErasure.pipe(
            Effect.provide(
              IntakeErasure.layer.pipe(
                Layer.provide(Layer.succeedContext(joinServices))
              )
            )
          );

    const redelivery =
      joinServices === undefined
        ? undefined
        : yield* IntakeRedeliver.pipe(
            Effect.provide(
              IntakeRedeliver.layer.pipe(
                Layer.provide(Layer.succeedContext(joinServices))
              )
            )
          );

    const assetBinding = Schema.decodeUnknownOption(AssetBindingSchema)(
      environment.ASSETS
    );

    const assets = Option.isNone(assetBinding)
      ? undefined
      : yield* StaticAssets.pipe(
          Effect.provide(StaticAssets.layer(assetBinding.value))
        );

    const contentStore = yield* ContentStore.pipe(
      Effect.provide(
        ContentStore.layer.pipe(
          Layer.provide(
            Layer.succeed(
              StaticAssets,
              assets ??
                Option.getOrElse(
                  yield* Effect.serviceOption(StaticAssets),
                  () => StaticAssets.unavailable
                )
            )
          )
        )
      )
    );

    const workerRoutes = mischiefRoutes({
      assets,
      contentStore,
      feedback,
      flags: liveFlags,
      interest:
        interest === undefined
          ? undefined
          : { ...interest, applications, erasure, redelivery },
      joinTokens: interestServices,
      legacyMcp,
      rateLimits,
      staticCache: cloudflareStaticCache,
      webBotAuth: {
        enabled: webBotAuthEnabled,
        privateJwk: webBotAuthPrivateJwk.pipe(
          Option.map(Redacted.value),
          Option.getOrUndefined
        ),
      },
    }).pipe(
      Layer.provide(layerWorkerLoader(loader, sandboxLimits)),
      Layer.provide(
        joinServices === undefined
          ? Layer.empty
          : Layer.succeedContext(joinServices)
      )
    );

    const website = Schema.decodeUnknownEffect(AssetBindingSchema)(
      environment.WEBSITE
    );

    const app = (yield* HttpRouter.toHttpEffect(workerRoutes).pipe(
      Effect.orDie
    )).pipe(
      Effect.provideService(ErrorPageRenderer, websiteErrorPages(website))
    );

    const readerApp = withReaderWebsite(
      website.pipe(Effect.orDie),
      readerResponseHeaders(contentStore)
    )(app);

    return {
      fetch: observeRequestLog(
        observeRequestIncidents(
          capture === undefined
            ? readerApp
            : Effect.gen(function* captureWithLiveIdentity() {
                const currentIdentity =
                  liveFlags === undefined
                    ? identityMode
                    : yield* liveFlags
                        .get(eventsIdentityMode, {})
                        .pipe(
                          Effect.catch((error) =>
                            Effect.logError(
                              "Flag read failed; using Config fallback.",
                              error
                            ).pipe(Effect.andThen(Effect.succeed(identityMode)))
                          )
                        );

                return yield* capture({
                  captureCity: true,
                  identityMode: currentIdentity,
                  runInBackground: inBackground,
                })(readerApp);
              })
        ).pipe(Effect.provide(webCryptoLayer))
      ),
    };
  });

const makeMischiefWorker = Effect.gen(function* makeMischiefWorker() {
  if (globalThis.__ALCHEMY_RUNTIME__ !== true) {
    yield* Cloudflare.WorkerLoader("CODE_SANDBOX");
  }

  const feedback = (yield* feedbackInfrastructure).pipe(Option.getOrUndefined);
  const liveFlags = yield* Flags.pipe(Effect.provide(liveFlagsLayer));

  const legacyMcp = yield* LegacyMcp;
  const interests = yield* Interest;
  const interestIndex = yield* InterestIndex;
  const sweepCron = yield* Cloudflare.Workers.CronEventSource;

  const tokenSecret = yield* Config.option(
    Config.Redacted("INTEREST_TOKEN_SECRET")
  );

  const typesafeApiKey = yield* Config.option(
    Config.Redacted("TYPESAFE_API_KEY")
  );

  const agentSignup = Option.isNone(tokenSecret)
    ? undefined
    : ({
        applications: intakeApplicationsLayer(
          () => interestIndex.getByName("index").applicationIds(),
          (actor) => interests.getByName(intakeInstance(actor))
        ),
        contacts: (submissionId: string) =>
          interests.getByName(`join:${submissionId}`),
        intake: intakeLiveLayer({
          interests: (name) => interests.getByName(name),
          tokenSecret: tokenSecret.value,
          typesafeApiKey,
        }).pipe(Layer.provide(FetchHttpClient.layer)),
        markPending: (submissionId, pending) =>
          interestIndex.getByName("index").markPending(submissionId, pending),
        noteApplication: (submissionId) =>
          interestIndex.getByName("index").noteApplication(submissionId),
        sweep: {
          ids: () => interestIndex.getByName("index").pendingIds(),
          schedule: (run) => sweepCron(SWEEP_PENDING_INTAKE_CRON, () => run),
        },
      } satisfies AgentSignupOptions | undefined);

  const enabled = yield* Flags.use((flags) =>
    flags.get(eventsEnabled, {}).pipe(Effect.orDie)
  ).pipe(Effect.provide(flagsLayer));

  const capture = yield* eventsFor({ enabled, id: "Mischief" });

  return yield* makeMischief(
    {
      forward: (session, request) => {
        const headers = new Headers(request.headers);
        headers.set(LEGACY_SESSION_HEADER, session);

        return legacyMcp
          .getByName(session)
          .fetch(HttpServerRequest.fromWeb(new Request(request, { headers })))
          .pipe(
            Effect.map((response) => HttpServerResponse.toWeb(response)),
            Effect.orDie
          );
      },
    },
    interestDirectoryLayer(
      (address) => interests.getByName(address),
      () => interestIndex.getByName("index")
    ),
    capture,
    agentSignup,
    feedback,
    liveFlags
  );
}).pipe(
  Effect.provide(
    Layer.mergeAll(
      Cloudflare.Workers.RateLimitBinding,
      Cloudflare.Workers.FetchBinding,
      Cloudflare.Workers.CronEventSourceLive,
      outerHttpPrivacyRegistration,
      privateTelemetry
    )
  ),
  Effect.tapCause((cause) =>
    logRequestIncident(cause, "initialization").pipe(
      Effect.provide(webCryptoLayer),
      Effect.asVoid
    )
  )
);

export default class Mischief extends Cloudflare.Worker<Mischief>()(
  "Mischief",
  Effect.gen(function* mischiefProps() {
    const traces = yield* traceSettings.pipe(Effect.orDie);

    const assets = yield* contentAssetsForBuild(
      new URL("../dist/content", import.meta.url).pathname,
      staticAssetGeneration
    ).pipe(Effect.orDie);

    return {
      assets,
      build: feedbackGatewayBuild,
      compatibility: { date: traces.enabled ? "2026-07-28" : "2026-05-28" },
      dev: { port: 1337 },
      domain: { name: "ratstack.sh", redirects: ["www.ratstack.sh"] },
      env: { MISCHIEF_CONFIG_FINGERPRINT: mischiefConfigFingerprint },
      main: import.meta.url,
      observability: traceObservability(traces),
      tailConsumers: [yield* CrashTail],
    };
  }),
  makeMischiefWorker
) {}

import { ResourceNotFound } from "@rat-stack/core/contracts";
import { Effect, Option, Schema } from "effect";
import { Command } from "foldkit";
import { load, pushUrl, replaceUrl } from "foldkit/navigation";
import { fromString } from "foldkit/url";

import { Message } from "./message.js";
import { DocumentQueries } from "./queries.js";

export const SearchDocs = Command.define("SearchDocs", {
  args: { generation: Schema.Finite, query: Schema.String },
  execute: ({ query, generation }) =>
    DocumentQueries.use((queries) => queries.search(query)).pipe(
      Effect.map((result) => Message.SucceededSearch({ generation, result })),
      Effect.orElseSucceed(() => Message.FailedSearch({ generation }))
    ),
  messages: [Message.SucceededSearch, Message.FailedSearch],
});

export const ReadDoc = Command.define("ReadDoc", {
  args: { generation: Schema.Finite, id: Schema.String },
  execute: ({ id, generation }) =>
    DocumentQueries.use((queries) => queries.read(id)).pipe(
      Effect.match({
        onFailure: (error) =>
          Message.FailedRead({
            generation,
            message: Schema.is(ResourceNotFound)(error)
              ? error.message
              : "The document could not be loaded. Try again in a moment.",
            notFound: Schema.is(ResourceNotFound)(error),
          }),
        onSuccess: (document) =>
          Message.SucceededRead({ document, generation }),
      })
    ),
  messages: [Message.SucceededRead, Message.FailedRead],
});

export const Navigate = Command.define("Navigate", {
  args: { url: Schema.String },
  execute: ({ url }) =>
    pushUrl(url).pipe(
      Effect.andThen(
        Effect.sync(() => {
          window.scrollTo(0, 0);
        })
      ),
      Effect.as(Message.CompletedNavigate())
    ),
  messages: [Message.CompletedNavigate],
});

export const ReadLocation = Command.define("ReadLocation", {
  execute: Effect.sync(() =>
    Option.match(fromString(window.location.href), {
      onNone: () => Message.CompletedNavigate(),
      onSome: (url) => Message.ChangedUrl({ url }),
    })
  ),
  messages: [Message.ChangedUrl, Message.CompletedNavigate],
});

export const ReplaceUrl = Command.define("ReplaceUrl", {
  args: { url: Schema.String },
  execute: ({ url }) =>
    replaceUrl(url).pipe(Effect.as(Message.CompletedNavigate())),
  messages: [Message.CompletedNavigate],
});

export const LoadExternal = Command.define("LoadExternal", {
  args: { href: Schema.String },
  execute: ({ href }) =>
    load(href).pipe(Effect.as(Message.CompletedLoadExternal())),
  messages: [Message.CompletedLoadExternal],
});

import { ReadOutput, SearchOutput } from "@rat-stack/core/contracts";
import { Schema } from "effect";
import { defineMessageUnion } from "foldkit/message";
import { UrlRequest } from "foldkit/navigation";
import { Url } from "foldkit/url";

export const Message = defineMessageUnion({
  ChangedUrl: { url: Url },
  ClickedLink: { request: UrlRequest },
  CompletedLoadExternal: {},
  CompletedNavigate: {},
  FailedRead: {
    generation: Schema.Finite,
    message: Schema.String,
    notFound: Schema.Boolean,
  },
  FailedSearch: { generation: Schema.Finite },
  SubmittedSearch: {},
  SucceededRead: { document: ReadOutput, generation: Schema.Finite },
  SucceededSearch: { generation: Schema.Finite, result: SearchOutput },
  UpdatedQuery: { value: Schema.String },
});

export type AppMessage = typeof Message.Type;

import { toRpcGroup } from "@rat-stack/capability/rpc-group";
import { readContract, searchContract } from "@rat-stack/core/contracts";
import { Cache, Context, Effect, Layer } from "effect";
import { FetchHttpClient } from "effect/http";
import { RpcClient, RpcSerialization } from "effect/rpc";

const { group } = toRpcGroup([searchContract, readContract]);

const protocol = RpcClient.layerProtocolHttp({ url: "/rpc" }).pipe(
  Layer.provide([FetchHttpClient.layer, RpcSerialization.layerJson])
);

const make = Effect.gen(function* makeDocumentQueries() {
  const client = yield* RpcClient.make(group).pipe(Effect.provide(protocol));

  const search = yield* Cache.make({
    capacity: Number.POSITIVE_INFINITY,
    lookup: (query: string) => client.search({ limit: 10, query }),
    timeToLive: "30 seconds",
  });

  const read = yield* Cache.make({
    capacity: Number.POSITIVE_INFINITY,
    lookup: (id: string) => client.read({ id }),
  });

  return {
    read: (id: string) => Cache.get(read, id),
    search: (query: string) => Cache.get(search, query),
  };
});

export class DocumentQueries extends Context.Service<
  DocumentQueries,
  Effect.Success<typeof make>
>()("@rat-stack/web/DocumentQueries", { make }) {
  static readonly layer = Layer.effect(this, this.make);
}

import { Button, Input } from "@foldkit/ui";
import * as stylex from "@stylexjs/stylex";
import { Option, Schema } from "effect";
import { Submodel } from "foldkit";
import type { Update } from "foldkit";
import type { Html, HtmlBuilder } from "foldkit/html";
import { UrlRequest } from "foldkit/navigation";
import { toString as urlToString } from "foldkit/url";
import type { Url } from "foldkit/url";

import {
  LoadExternal,
  Navigate,
  ReadDoc,
  ReadLocation,
  ReplaceUrl,
  SearchDocs,
} from "../client/docs/command.js";
import { Message } from "../client/docs/message.js";
import type { AppMessage } from "../client/docs/message.js";
import { initialModel, ReadState, SearchState } from "../client/docs/model.js";
import type { AppModel } from "../client/docs/model.js";
import type { DocumentQueries } from "../client/docs/queries.js";
import { resultCount, searchCopy } from "./docs-copy.js";
import { docsStyles } from "./docs.stylex.js";
import { AppRoute, docsSearchRouter, parseRoute } from "./route.js";
import type { AppRouteState } from "./route.js";
import { agentGuideRouter } from "./site-route.js";

type DocsReturn = Update.Return<AppModel, AppMessage, DocumentQueries>;

const className = (style: stylex.StyleXStyles) =>
  stylex.props(style).className ?? "";

const searchFor = (model: AppModel, query: string): DocsReturn => {
  const generation = model.generation + 1;

  return {
    commands: [SearchDocs({ generation, query })],
    model: { ...model, generation, query, search: SearchState.Loading() },
  };
};

const enterRoute = (model: AppModel, route: AppRouteState): DocsReturn => {
  const next = {
    ...model,
    generation: model.generation + 1,
    read: ReadState.Idle(),
    route,
    search: Schema.is(SearchState.Loading)(model.search)
      ? SearchState.Idle()
      : model.search,
  };

  return AppRoute.match<DocsReturn>(route, {
    NotFound: () => ({ model: next }),
    Read: ({ id }) =>
      id.trim().length === 0
        ? {
            model: {
              ...next,
              read: ReadState.Failed({
                message: "No document was selected.",
                notFound: false,
              }),
            },
          }
        : {
            commands: [ReadDoc({ generation: next.generation, id })],
            model: { ...next, read: ReadState.Loading() },
          },
    Search: ({ q }) => {
      const query = Option.getOrElse(q, () => "").trim();

      return query.length === 0
        ? { model: next }
        : searchFor({ ...next, generation: model.generation }, query);
    },
  });
};

export const init = (url: Url): DocsReturn =>
  enterRoute(initialModel, parseRoute(url));

export const boot: DocsReturn = {
  commands: [ReadLocation()],
  model: initialModel,
};

export const update = (model: AppModel, message: AppMessage): DocsReturn =>
  Message.match<DocsReturn>(message, {
    ChangedUrl: ({ url }) => enterRoute(model, parseRoute(url)),
    ClickedLink: ({ request }) =>
      UrlRequest.match<DocsReturn>(request, {
        External: ({ href }) => ({
          commands: [LoadExternal({ href })],
          model,
        }),
        Internal: ({ url }) => ({
          commands: [Navigate({ url: urlToString(url) })],
          model,
        }),
      }),
    CompletedLoadExternal: () => ({ model }),
    CompletedNavigate: () => ({ model }),
    FailedRead: ({ generation, message: error, notFound }) => ({
      model:
        generation === model.generation
          ? { ...model, read: ReadState.Failed({ message: error, notFound }) }
          : model,
    }),
    FailedSearch: ({ generation }) => ({
      model:
        generation === model.generation
          ? { ...model, search: SearchState.Failed() }
          : model,
    }),
    SubmittedSearch: () => {
      const query = model.query.trim();

      if (query.length === 0) {
        return { model };
      }

      const searched = searchFor(model, query);

      return {
        commands: [
          ...(searched.commands ?? []),
          ReplaceUrl({ url: docsSearchRouter({ q: Option.some(query) }) }),
        ],
        model: searched.model,
      };
    },
    SucceededRead: ({ generation, document }) => ({
      model:
        generation === model.generation
          ? { ...model, read: ReadState.Loaded({ document }) }
          : model,
    }),
    SucceededSearch: ({ generation, result }) => ({
      model:
        generation === model.generation
          ? { ...model, search: SearchState.Loaded({ result }) }
          : model,
    }),
    UpdatedQuery: ({ value }) => ({ model: { ...model, query: value } }),
  });

const searchResults = (model: AppModel, h: HtmlBuilder<AppMessage>): Html =>
  SearchState.match<Html>(model.search, {
    Failed: () =>
      h.p([h.Role("alert")], ["Search failed. Try again in a moment."]),
    Idle: () => h.p([], ["Matches appear here."]),
    Loaded: ({ result }) =>
      h.div(
        [],
        [
          h.p([], [resultCount(result.total)]),
          h.ul(
            [h.Class(className(docsStyles.results))],
            result.matches.map((match) =>
              h.li(
                [h.Key(match.id), h.Class(className(docsStyles.match))],
                [
                  h.h2([], [h.a([h.Href(match.routePath)], [match.title])]),
                  h.p(
                    [h.Class(className(docsStyles.meta))],
                    [`${match.kind} · ${match.routePath}`]
                  ),
                  h.p([], [match.description]),
                  h.p([], [match.excerpt]),
                ]
              )
            )
          ),
        ]
      ),
    Loading: () => h.p([], ["Searching the docs…"]),
  });

const searchView = (model: AppModel, h: HtmlBuilder<AppMessage>): Html =>
  h.section(
    [h.AriaLabel(searchCopy.heading)],
    [
      h.p(
        [],
        [
          `${searchCopy.intro} `,
          h.a([h.Href(agentGuideRouter())], ["The agent guide"]),
          ` ${searchCopy.agents}`,
        ]
      ),
      h.noscript([], [searchCopy.noscript]),
      h.div(
        [h.Class(className(docsStyles.form)), h.Role("search")],
        [
          h.label(
            [h.For("docs-query"), h.Class("visually-hidden")],
            [searchCopy.heading]
          ),
          Input.view(
            {
              id: "docs-query",
              name: "q",
              onInput: (value) => Message.UpdatedQuery({ value }),
              placeholder: "Try ‘capability’ or ‘Effect’",
              toView: ({ input }) =>
                h.input([
                  ...input,
                  h.Class(className(docsStyles.input)),
                  h.Autocomplete("off"),
                  h.OnKeyDownPreventDefault((key) =>
                    key === "Enter"
                      ? Option.some(Message.SubmittedSearch())
                      : Option.none()
                  ),
                ]),
              type: "text",
              value: model.query,
            },
            h
          ),
          Button.view(
            {
              onClick: Message.SubmittedSearch(),
              toView: ({ button }) => h.button(button, ["Search"]),
              type: "button",
            },
            h
          ),
        ]
      ),
      h.section(
        [
          h.AriaLabel("Matches"),
          h.AriaLive("polite"),
          h.AriaBusy(Schema.is(SearchState.Loading)(model.search)),
        ],
        [searchResults(model, h)]
      ),
    ]
  );

const backToSearch = (h: HtmlBuilder<AppMessage>, label: string) =>
  h.p([], [h.a([h.Href(docsSearchRouter({ q: Option.none() }))], [label])]);

const readView = (model: AppModel, h: HtmlBuilder<AppMessage>): Html =>
  h.section(
    [h.AriaLabel("Document")],
    [
      backToSearch(h, "← Back to search"),
      ReadState.match<Html>(model.read, {
        Failed: ({ message, notFound }) =>
          h.div(
            [],
            [
              h.h2(
                [],
                [notFound ? "Document not found" : "Document unavailable"]
              ),
              h.p([h.Role("alert")], [message]),
            ]
          ),
        Idle: () => h.p([], ["Loading the document…"]),
        Loaded: ({ document }) =>
          h.article(
            [],
            [
              h.h2([], [document.title]),
              h.p(
                [h.Class(className(docsStyles.meta))],
                [`${document.kind} · ${document.routePath}`]
              ),
              h.p([], [document.description]),
              h.p(
                [],
                [h.a([h.Href(document.routePath)], ["Open the full page"])]
              ),
              h.pre(
                [h.Class(className(docsStyles.documentText))],
                [document.text]
              ),
            ]
          ),
        Loading: () => h.p([h.Role("status")], ["Loading the document…"]),
      }),
    ]
  );

export const view = Submodel.defineView<AppModel, AppMessage>((model, h) =>
  AppRoute.match<Html>(model.route, {
    NotFound: () =>
      h.section(
        [h.AriaLabel("Page not found")],
        [h.h2([], ["Page not found"]), backToSearch(h, "Back to search")]
      ),
    Read: () => readView(model, h),
    Search: () => searchView(model, h),
  })
);

import * as Cloudflare from "@alchemy.run/cloudflare";
import * as Output from "alchemy/Output";
import "alchemy/Phase";
import { retain } from "alchemy/RemovalPolicy";
import { Stage } from "alchemy/Stage";
import { Config, ConfigProvider, Effect } from "effect";
import { identity } from "effect/Function";

const retainInProd =
  globalThis.__ALCHEMY_RUNTIME__ === true
    ? identity
    : retain(Stage.pipe(Effect.map((stage) => stage === "prod")));

export const basinStream = (name: string) =>
  Effect.gen(function* declareBasinStream() {
    const bucket = yield* Cloudflare.R2.Bucket(`${name}Bucket`, {}).pipe(
      retainInProd
    );

    const stream = yield* Cloudflare.Pipelines.Stream(`${name}Stream`, {
      http: { enabled: false },
    }).pipe(retainInProd);

    return { bucket, stream } as const;
  });

const sinkToken = Config.Redacted("EVENTS_SINK_TOKEN").pipe(
  Effect.provideService(ConfigProvider.ConfigProvider, ConfigProvider.fromEnv())
);

export type CatalogMaintenance = Pick<
  Cloudflare.R2.DataCatalogProps,
  "compaction" | "snapshotExpiration"
>;

export interface IcebergSinkOptions {
  readonly bucketName: Output.Output<string>;
  readonly maintenance?: CatalogMaintenance;
  readonly name: string;
  readonly streamName: Output.Output<string>;
  readonly table: string;
}

export const icebergSink = ({
  bucketName,
  maintenance = {},
  name,
  streamName,
  table,
}: IcebergSinkOptions) =>
  Effect.gen(function* declareIcebergSink() {
    const token = yield* sinkToken;

    const catalog = yield* Cloudflare.R2.DataCatalog(`${name}Catalog`, {
      ...maintenance,
      bucketName,
      token,
    }).pipe(retainInProd);

    const sink = yield* Cloudflare.Pipelines.Sink(`${name}Sink`, {
      config: {
        bucket: catalog.bucketName,
        namespace: "default",
        tableName: table,
        token,
      },
      format: { compression: "zstd", type: "parquet" },
      type: "r2_data_catalog",
    }).pipe(retainInProd);

    return yield* Cloudflare.Pipelines.Pipeline(`${name}Pipeline`, {
      sql: Output.interpolate`INSERT INTO ${sink.name} SELECT * FROM ${streamName}`,
    }).pipe(retainInProd);
  });

import { Context, Effect, Layer, Option, Schema } from "effect";

import { sourceLines } from "./model.ts";
import type { CodeRequest } from "./model.ts";
import { SourceRepository } from "./source-repository.ts";

export const DiagnosticsSchema = Schema.Struct({
  line: Schema.Finite,
  message: Schema.String,
  sourcePath: Schema.String,
});

export type Diagnostics = typeof DiagnosticsSchema.Type;

export class Drift extends Context.Service<
  Drift,
  {
    readonly check: (
      request: CodeRequest,
      source: string
    ) => Effect.Effect<readonly Diagnostics[]>;
  }
>()("code-snippets/Drift") {
  static readonly silent = Layer.succeed(
    Drift,
    Drift.of({ check: () => Effect.succeed([]) })
  );
  static readonly layer = Layer.effect(
    Drift,
    Effect.gen(function* makeDrift() {
      const repository = yield* SourceRepository;

      const check = Effect.fn("Drift.check")(function* check(
        request: CodeRequest,
        source: string
      ) {
        if (!request.reference) {
          return [];
        }

        const head = yield* repository
          .resolve(request.repo, "HEAD", request.path)
          .pipe(Effect.option);

        if (Option.isNone(head)) {
          return [
            {
              line: request.line,
              message: `pinned at ${request.commit}; HEAD comparison unavailable; refresh?`,
              sourcePath: request.sourcePath,
            },
          ];
        }

        const previous = sourceLines(source);
        const current = sourceLines(head.value);
        let changed = 0;

        for (const range of request.ranges) {
          for (let line = range.start; line <= range.end; line += 1) {
            if (previous[line - 1] !== current[line - 1]) {
              changed += 1;
            }
          }
        }

        return changed === 0
          ? []
          : [
              {
                line: request.line,
                message: `pinned at ${request.commit}; these lines changed since (${changed} shown lines differ at HEAD); refresh?`,
                sourcePath: request.sourcePath,
              },
            ];
      });

      return Drift.of({ check });
    })
  );
}

