import { watchActor } from "@rat-stack/capability/actor-watch";
import {
  createEffectActor,
  createEffectLogic,
  join,
  setupEffect,
} from "@xstate/effect";
import { Data, Effect, Schema } from "effect";
import type { Cause } from "effect";
import { types } from "xstate";

import { FileInspector } from "./file-inspector.js";
import type { FileStats, FileStatsError } from "./stats.js";

export type InspectOutcome = Data.TaggedEnum<{
  Inspected: { readonly stats: FileStats };
  Unreadable: { readonly cause: Cause.Cause<FileStatsError> };
}>;

export const inspectOutcome = Data.taggedEnum<InspectOutcome>();

interface InspectContext {
  readonly outcome: InspectOutcome | undefined;
  readonly path: string;
}

const readStats = createEffectLogic({
  effect: ({ input }) =>
    FileInspector.use((inspector) => inspector.inspect(input.path)),
  schemas: { input: Schema.Struct({ path: Schema.String }) },
});

export const inspectMachine = setupEffect({
  actors: { readStats },
  schemas: {
    context: types<InspectContext>(),
    input: Schema.Struct({ path: Schema.String }),
  },
}).createMachine({
  context: ({ input }) => ({ outcome: undefined, path: input.path }),
  initial: "reading",
  output: ({ context }) => context.outcome,
  states: {
    inspected: { type: "final" },
    reading: {
      invoke: {
        input: ({ context }) => ({ path: context.path }),
        onDone: {
          context: ({ event }) => ({
            outcome: inspectOutcome.Inspected({ stats: event.output }),
          }),
          target: "inspected",
        },
        onError: {
          context: ({ event }) => ({
            outcome: inspectOutcome.Unreadable({ cause: event.error.cause }),
          }),
          target: "unreadable",
        },
        src: "readStats",
      },
    },
    unreadable: { type: "final" },
  },
});

export const runInspectMachine = Effect.fn("runInspectMachine")(
  function* runInspectMachine(path: string) {
    const actor = yield* createEffectActor(inspectMachine, { input: { path } });
    yield* watchActor("inspectMachine", actor);
    // @effect-diagnostics-next-line anyUnknownInErrorContext:off -- A machine-level error or an early stop is a programming error here: the domain failure travels through the `unreadable` state, not the actor. A machine's ErrorFrom is unknown by design (statelyai/xstate#5725), so the unknown-error diagnostic is off for this one call and orDie closes it.
    const outcome = yield* join(actor).pipe(Effect.orDie);

    if (outcome === undefined) {
      return yield* Effect.die(
        new Error("inspectMachine completed without an outcome")
      );
    }

    return yield* inspectOutcome.$match(outcome, {
      Inspected: ({ stats }) => Effect.succeed(stats),
      Unreadable: ({ cause }) => Effect.failCause(cause),
    });
  },
  Effect.scoped
);

import { NodeServices } from "@effect/platform-node";
import { expect, it } from "@effect/vitest";
import { createEffectActor, join } from "@xstate/effect";
import { Cause, Effect, FileSystem, Layer, Path, Schema } from "effect";

import { FileInspector } from "../src/file-inspector.js";
import {
  inspectMachine,
  inspectOutcome,
  runInspectMachine,
} from "../src/inspect-machine.js";
import { FileStatsError } from "../src/stats.js";

const TestLayer = Layer.provideMerge(FileInspector.layer, NodeServices.layer);

const runMachine = Effect.fn("runMachine")(function* runMachine(path: string) {
  const actor = yield* createEffectActor(inspectMachine, { input: { path } });
  // @effect-diagnostics-next-line anyUnknownInErrorContext:off -- A machine's ErrorFrom is unknown (statelyai/xstate#5725); a machine-level error here is a test failure, not a case under test.
  const outcome = yield* join(actor).pipe(Effect.orDie);

  return { outcome, state: actor.getSnapshot().value };
});

it.layer(TestLayer)("inspectMachine", (test) => {
  test.effect("reaches the inspected final state with stats as output", () =>
    Effect.gen(function* reachesInspected() {
      const fileSystem = yield* FileSystem.FileSystem;
      const path = yield* Path.Path;
      const directory = yield* fileSystem.makeTempDirectoryScoped();
      const file = path.join(directory, "notes.txt");
      yield* fileSystem.writeFileString(file, "one two\nthree\n");

      const { outcome, state } = yield* runMachine(file);

      expect(state).toBe("inspected");
      expect(inspectOutcome.$is("Inspected")(outcome)).toBe(true);
      expect(outcome).toMatchObject({ stats: { lines: 2, words: 3 } });
    })
  );

  test.effect("reaches the unreadable final state with the typed error", () =>
    Effect.gen(function* reachesUnreadable() {
      const { outcome, state } = yield* runMachine(
        "/definitely-not-here/notes.txt"
      );

      expect(state).toBe("unreadable");
      expect(
        inspectOutcome.$is("Unreadable")(outcome) &&
          Schema.is(FileStatsError)(Cause.squash(outcome.cause))
      ).toBe(true);
    })
  );

  test.effect(
    "runInspectMachine lifts the unreadable outcome into the error channel",
    () =>
      Effect.gen(function* liftsUnreadableIntoErrors() {
        const error = yield* Effect.flip(
          runInspectMachine("/definitely-not-here/notes.txt")
        );

        expect(error._tag).toBe("FileStatsError");
      })
  );
});

import * as Cloudflare from "@alchemy.run/cloudflare";
import { basinStream, icebergSink } from "@rat-stack/basin";
import {
  EventSink,
  EventSinkError,
  RawEventSchema,
} from "@rat-stack/core/event-sink";
import "alchemy/Phase";
import { Random } from "alchemy/Random";
import { retain } from "alchemy/RemovalPolicy";
import * as RuntimeContext from "alchemy/RuntimeContext";
import { Stage } from "alchemy/Stage";
import { Effect, Layer, Redacted, Schema } from "effect";
import { identity } from "effect/Function";

import { VisitorSalt } from "./visitor-salt.js";

export interface BasinOptions {
  readonly id: string;
}

export const EVENTS_TABLE = "events_raw";

const encodeRawEvent = Schema.encodeEffect(RawEventSchema);

export const unstructuredRow = (event: typeof RawEventSchema.Type) =>
  encodeRawEvent(event).pipe(Effect.map((value) => ({ value })));

const retainInProd =
  globalThis.__ALCHEMY_RUNTIME__ === true
    ? identity
    : retain(Stage.pipe(Effect.map((stage) => stage === "prod")));

export const basinFoundation = ({ id }: BasinOptions) =>
  Effect.gen(function* declareBasinFoundation() {
    const { bucket, stream } = yield* basinStream(`${id}Events`);
    const salt = yield* Random(`${id}VisitorSalt`).pipe(retainInProd);

    return { bucket, salt, stream } as const;
  });

export const Basin = ({ id }: BasinOptions) =>
  Layer.unwrap(
    Effect.gen(function* buildBasinEvents() {
      const { bucket, salt, stream } = yield* basinFoundation({ id });

      if (globalThis.__ALCHEMY_RUNTIME__ !== true) {
        yield* icebergSink({
          bucketName: bucket.bucketName,
          name: `${id}Events`,
          streamName: stream.name,
          table: EVENTS_TABLE,
        });
      }

      const saltValue = yield* salt.text;
      const writer = yield* Cloudflare.Pipelines.WriteStream(stream);

      return Layer.mergeAll(
        Layer.succeed(EventSink, {
          send: (events) =>
            Effect.forEach((event: (typeof events)[number]) =>
              unstructuredRow(event)
            )(events).pipe(
              Effect.flatMap((records) => writer.send(records)),
              Effect.mapError((cause) => new EventSinkError({ cause })),
              Effect.provide(RuntimeContext.RuntimeContext.phantom)
            ),
        }),
        Layer.succeed(VisitorSalt, {
          salt: saltValue.pipe(Effect.map((secret) => Redacted.value(secret))),
        })
      );
    })
  ).pipe(Layer.provide(Cloudflare.Pipelines.WriteStreamBinding));

