  ["svelte", "svelte"],
  ["html", "html"],
  ["sql", "sql"],
  ["sh", "bash"],
  ["yaml", "yaml"],
  ["yml", "yaml"],
  ["toml", "toml"],
  ["txt", "text"],
  ["svx", "markdown"],
  ["md", "markdown"],
]);

export const normalizeCodeLanguage = (language: string) => {
  const aliases = new Map([
    ["ts", "typescript"],
    ["js", "javascript"],
    ["sh", "bash"],
    ["shell", "bash"],
    ["yml", "yaml"],
    ["txt", "text"],
    ["svx", "markdown"],
    ["md", "markdown"],
  ]);

  const normalized = language.trim().toLowerCase();

  return (
    aliases.get(normalized) ?? (normalized === "" ? "markdown" : normalized)
  );
};

export type { Token } from "./tokens.ts";

export { TokenSchema, SnippetLine } from "./tokens.ts";

import { Runtime, Schema } from "effect";

export const FileStatsSchema = Schema.Struct({
  bytes: Schema.Int,
  characters: Schema.Int,
  lines: Schema.Int,
  path: Schema.String,
  words: Schema.Int,
});

export type FileStats = typeof FileStatsSchema.Type;

export class FileStatsError extends Schema.TaggedError<
  FileStatsError,
  { readonly brand: unique symbol }
>()("FileStatsError", {
  path: Schema.String,
  reason: Schema.String,
}) {
  override readonly [Runtime.errorExitCode] = 1;
  override readonly [Runtime.errorReported] = false;

  override get message(): string {
    return `Could not read ${this.path}: ${this.reason}`;
  }
}

export const summarizeText = (path: string, text: string): FileStats => {
  const trailingLineBreak = /(?:\r\n|\r|\n)$/u.test(text);

  const lines =
    text.length === 0
      ? 0
      : text.split(/\r\n|\r|\n/u).length - (trailingLineBreak ? 1 : 0);

  return {
    bytes: new TextEncoder().encode(text).byteLength,
    characters: text.match(/./gsu)?.length ?? 0,
    lines,
    path,
    words: text.match(/\S+/gu)?.length ?? 0,
  };
};

export const summarizeBytes = (
  path: string,
  content: Uint8Array
): FileStats => ({
  ...summarizeText(path, new TextDecoder().decode(content)),
  bytes: content.byteLength,
});

export const formatFileStats = (stats: FileStats): string =>
  [
    stats.path,
    `  bytes:      ${stats.bytes}`,
    `  characters: ${stats.characters}`,
    `  words:      ${stats.words}`,
    `  lines:      ${stats.lines}`,
  ].join("\n");

