        load: state.storage
          .get<InterestRecord>(RECORD_KEY)
          .pipe(Effect.provideContext(runtime)),
        save: (record: InterestRecord) =>
          state.storage
            .put(RECORD_KEY, record)
            .pipe(Effect.provideContext(runtime)),
      };

