`;

const ChildMessage = Schema.Union([
  Schema.Struct({
    id: Schema.Finite,
    input: Schema.Json,
    name: Schema.String,
    type: Schema.Literal("call"),
  }),
  Schema.Struct({
    logs: Schema.Array(Schema.String),
    result: Schema.Unknown,
    type: Schema.Literal("done"),
  }),
  Schema.Struct({
    diagnostic: Schema.optionalKey(SandboxDiagnostic),
    logs: Schema.Array(Schema.String),
    message: Schema.String,
    reason: Schema.optional(Schema.Literals(["threw", "timeout"])),
    type: Schema.Literal("error"),
  }),
]);

const decodeChildMessage = Schema.decodeUnknownEffect(
  Schema.fromJsonString(ChildMessage)
);

type HostMessage =
  | {
      readonly code: string;
      readonly names: readonly string[];
      readonly timeoutMillis: number;
      readonly type: "run";
    }
  | ({ readonly id: number; readonly type: "result" } & InvokeOutcome);

const encoder = new TextEncoder();

const isSandboxError = Schema.is(SandboxError);

export interface SubprocessOptions extends SandboxLimits {
  readonly timeout?: Duration.Input | undefined;
  readonly nodePath?: string | undefined;
}

const makeSubprocess = (options?: SubprocessOptions) =>
  Effect.gen(function* makeSubprocessSandbox() {
    const spawner = yield* ChildProcessSpawner.ChildProcessSpawner;
    const timeout = Duration.fromInputUnsafe(options?.timeout ?? "10 seconds");
    const nodePath = options?.nodePath ?? process.execPath;

    const command = ChildProcess.make(
      nodePath,
      [
        "--permission",
        "--disallow-code-generation-from-strings",
        "--input-type=module",
        "-e",
        RUNNER_SOURCE,
      ],
      {
        detached: true,
        env: {},
        extendEnv: false,
        forceKillAfter: "250 millis",
        killSignal: "SIGTERM",
      }
    );

    const run = Effect.fn("Sandbox.run")(function* run(
      code: string,
      invoke: Invoke,
      names: readonly string[]
    ) {
      const handle = yield* spawner.spawn(command).pipe(
        Effect.mapError(
          (error) =>
            new SandboxError({
              logs: [],
              message: error.message,
              reason: "exited",
            })
        )
      );

      const outbox = yield* Queue.unbounded<Uint8Array, Cause.Done>();
      yield* Stream.fromQueue(outbox).pipe(
        Stream.run(handle.stdin),
        Effect.ignore,
        Effect.forkScoped
      );

      const send = (message: HostMessage) =>
        Queue.offer(outbox, encoder.encode(`${JSON.stringify(message)}\n`));

      yield* send({
        code,
        names,
        timeoutMillis: Duration.toMillis(timeout),
        type: "run",
      });

      const outcome = yield* Stream.decodeText(handle.stdout).pipe(
        Stream.splitLines,
        Stream.filter((line) => line.trim() !== ""),
        Stream.mapEffect(
          (line) =>
            decodeChildMessage(line).pipe(
              Effect.mapError(
                (error) =>
                  new SandboxError({
                    logs: [],
                    message: `Unreadable sandbox message: ${error.message}`,
                    reason: "protocol",
                  })
              ),
              Effect.flatMap((message) => {
                if (message.type === "call") {
                  return invoke(message.name, message.input).pipe(
                    Effect.flatMap((result: InvokeOutcome) =>
                      send({ id: message.id, type: "result", ...result })
                    ),
                    Effect.andThen(Effect.succeedNone)
                  );
                }

                return Effect.succeedSome<SandboxRun | SandboxError>(
                  message.type === "done"
                    ? { logs: message.logs, result: message.result }
                    : new SandboxError({
                        diagnostic: message.diagnostic,
                        logs: message.logs,
                        message: message.message,
                        reason: message.reason ?? "threw",
                      })
                );
              })
            ),
          { concurrency: 8 }
        ),
        Stream.filter(Option.isSome),
        Stream.map((option) => option.value),
        Stream.runHead,
        Effect.mapError((error) =>
          isSandboxError(error)
            ? error
            : new SandboxError({
                logs: [],
                message: error.message,
                reason: "exited",
              })
        )
      );

      if (Option.isNone(outcome)) {
        return yield* new SandboxError({
          logs: [],
          message: "The sandbox exited before finishing the program",
          reason: "exited",
        });
      }

      if (isSandboxError(outcome.value)) {
        return yield* outcome.value;
      }

      return outcome.value;
    }, Effect.scoped);

    return {
      run: sandboxRunner(
        (code, invoke, names) =>
          run(code, invoke, names).pipe(
            Effect.timeoutOrElse({
              duration: timeout,
              orElse: () =>
                Effect.fail(
                  new SandboxError({
                    logs: [],
                    message: `The program did not finish within ${Duration.format(timeout)}`,
                    reason: "timeout",
                  })
                ),
            })
          ),
        options
      ),
    } as const;
  });

export const layerSubprocess = (
  options?: SubprocessOptions
): Layer.Layer<Sandbox, never, ChildProcessSpawner.ChildProcessSpawner> =>
  Layer.effect(Sandbox, makeSubprocess(options));

// @effect-diagnostics anyUnknownInErrorContext:off unsafeEffectTypeAssertion:off missingEffectContext:off -- See to-toolkit.ts: a projection over a heterogeneous list erases error and requirement types at the boundary and recovers them for callers.
import type { Layer } from "effect";
import { Effect, Match, Schema } from "effect";
import { Tool, Toolkit } from "effect/ai";

import { discoverCatalog, toCatalog, toTypeScript } from "./catalog-model.js";
import type { Catalog } from "./catalog-model.js";
import { defineContract, failureSchemaOf } from "./contract.js";
import type {
  AnyCapability,
  ApprovalRequirement,
  ContractOf,
  FailureSchemaOf,
} from "./contract.js";
import { ExecuteError, ExecuteFailure } from "./execute-error.js";
import { implement } from "./implement.js";
import { resolveLimits } from "./sandbox-limits-schema.js";
import { Sandbox } from "./sandbox-port.js";
import type {
  Invoke,
  InvokeOutcome,
  SandboxLimits,
} from "./sandbox-service.js";
import type { RequirementsOf } from "./to-toolkit.js";

export const SearchMatch = Schema.Struct({
  description: Schema.String,
  name: Schema.String,
  score: Schema.Finite,
  signature: Schema.String,
});

export const SearchResult = Schema.Struct({
  matches: Schema.Array(SearchMatch),
  next: Schema.optionalKey(
    Schema.NullOr(Schema.Struct({ offset: Schema.Int }))
  ),
  offset: Schema.optionalKey(Schema.Int),
  remaining: Schema.optionalKey(Schema.Int),
  total: Schema.Int,
});

export const ExecuteInput = Schema.Struct({
  code: Schema.String,
});

export const ExecuteResult = Schema.Struct({
  logs: Schema.Array(Schema.String),
  result: Schema.Json,
  toolCalls: Schema.optionalKey(Schema.Array(Schema.String)),
  truncated: Schema.optionalKey(Schema.Boolean),
});

const SearchInput = Schema.Struct({
  limit: Schema.optional(Schema.Int.check(Schema.isGreaterThan(0))),
  offset: Schema.optional(Schema.Natural),
  query: Schema.String,
});

const search = Tool.make("search", {
  description:
    "Find capabilities by intent. Returns each match's TypeScript signature for the `tools` object available to `execute`. Call this before `execute` when unsure what exists.",
  parameters: SearchInput,
  success: SearchResult,
})
  .annotate(Tool.Readonly, true)
  .annotate(Tool.Idempotent, true);

const searchPage = Effect.fnUntraced(function* searchCatalogPage(
  catalog: Catalog,
  query: string,
  limit: number,
  offset: number
) {
  const loaded = import("./catalog-search.js");

  const { searchCatalog } = yield* Effect.promise(
    loaded.finally.bind(loaded, undefined)
  );

  const all = searchCatalog(catalog, query, Number.MAX_SAFE_INTEGER);
  const matches = all.slice(offset, offset + limit);
  const remaining = Math.max(0, all.length - offset - matches.length);

  return {
    matches,
    next: remaining > 0 ? { offset: offset + matches.length } : null,
    offset,
    remaining,
    total: catalog.capabilities.length,
  };
});

const executeIntro =
  "Run a JavaScript program against the capabilities. The program is the body of an async function with `tools` in scope; `return` a JSON value to get it back, and `console.log` is captured into `logs`. Each `tools.<name>(input)` call is validated against that capability's input schema, runs on the host, and resolves with its output or rejects with its declared failure. Execution problems fail with a typed `ExecuteError` carrying kind, message, optional tag, logs, toolCalls, and truncated. `toolCalls` lists admitted calls in order. `truncated` marks output cuts. At most 8 tool calls run concurrently. Only host cancellation interrupts execution.";

const executeDescription = (
  discovery: ReturnType<typeof discoverCatalog>
): string =>
  [
    executeIntro,
    "",
    discovery.summary,
    ...(discovery.complete
      ? []
      : [
          "Call `search` first, or call `tools.$codemode.search({ query })` inside the program, to get full signatures for missing capabilities. Repeat the same query with `offset: next.offset` until `next` is null.",
        ]),
    ...(discovery.declarations === ""
      ? []
      : [
          "",
          "The `tools` object:",
          "",
          "```ts",
          discovery.declarations.trimEnd(),
          "```",
        ]),
  ].join("\n");

export type DeclarationPlacement = "inline" | "search";

export interface ExecuteOptions extends SandboxLimits {
  readonly declarations?: DeclarationPlacement | undefined;
  readonly catalogBudget?: number | undefined;
}

export interface CodeModeOptions extends ExecuteOptions {
  readonly searchLimit?: number | undefined;
}

type NeedsApprovalOf<Caps extends readonly AnyCapability[]> =
  true extends ContractOf<Caps[number]>["needsApproval"] ? true : false;

export interface CodeModeProjection<Caps extends readonly AnyCapability[]> {
  readonly catalog: Catalog;
  readonly declarations: string;
  readonly toolkit: Toolkit.Toolkit<{
    readonly search: typeof search;
    readonly execute: Tool.Tool<
      "execute",
      {
        readonly parameters: Schema.Struct<{ readonly code: Schema.String }>;
        readonly success: typeof ExecuteResult;
        readonly failure: FailureSchemaOf<
          typeof ExecuteFailure,
          NeedsApprovalOf<Caps>
        >;
        readonly failureMode: "error";
      }
    >;
  }>;
  readonly layer: Layer.Layer<
    Tool.HandlersFor<CodeModeProjection<Caps>["toolkit"]["tools"]>,
    never,
    RequirementsOf<Caps> | ApprovalRequirement<NeedsApprovalOf<Caps>> | Sandbox
  >;
}

export const invokerFor = <const Caps extends readonly AnyCapability[]>(
  capabilities: Caps
): Effect.Effect<Invoke, never, RequirementsOf<Caps>> =>
  Effect.gen(function* buildInvoker() {
    const diagnostics = import("./sandbox-diagnostic.js");

    const { toolDiagnostic } = yield* Effect.promise(
      diagnostics.finally.bind(diagnostics, undefined)
    );

    const invocation = import("./sandbox-invoke.js");

    const { invokeFailure } = yield* Effect.promise(
      invocation.finally.bind(invocation, undefined)
    );

    const context = yield* Effect.context<RequirementsOf<Caps>>();

    const byName = new Map(
      capabilities.map(
        (capability) => [capability.contract.name, capability] as const
      )
    );

    const invoke: Invoke = (name, input) => {
      const item = byName.get(name);

      if (item === undefined) {
        return Effect.succeed(
          invokeFailure("UnknownCapability", `No capability named ${name}`)
        );
      }

      // SAFETY: `AnyCapability` erased this capability's requirements to `unknown`; they are a subset of `RequirementsOf<Caps>`, which `context` carries. The input is decoded by its schema first.
      // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- projection boundary erases the handler type; RequirementsOf<Caps> restores it.
      const run = item.handler as (
        // oxlint-disable-next-line anti-slop/no-unknown-parameters -- the sandbox decodes the input with the capability schema before this handler runs.
        input: unknown
      ) => Effect.Effect<unknown, unknown, RequirementsOf<Caps>>;

      const encodeOutput = Schema.encodeUnknownEffect(item.contract.output);

      const encodeFailure = Schema.encodeUnknownEffect(
        failureSchemaOf(item.contract)
      );

      return Schema.decodeUnknownEffect(item.contract.input)(input).pipe(
        Effect.matchEffect({
          onFailure: () =>
            Effect.succeed(
              invokeFailure(
                "InvalidInput",
                "Capability input does not match its schema"
              )
            ),
          onSuccess: (decoded) =>
            run(decoded).pipe(
              Effect.provideContext(context),
              Effect.matchEffect({
                onFailure: (error) =>
                  encodeFailure(error).pipe(
                    Effect.map((encoded): InvokeOutcome => ({
                      diagnostic: toolDiagnostic(encoded),
                      error: encoded,
                      ok: false,
                    })),
                    Effect.orElseSucceed(() =>
                      invokeFailure(
                        "UnencodableFailure",
                        "Capability failure does not match its declared schema"
                      )
                    )
                  ),
                onSuccess: (output) =>
                  encodeOutput(output).pipe(
                    Effect.map((value): InvokeOutcome => ({
                      ok: true,
                      value,
                    })),
                    Effect.orElseSucceed(() =>
                      invokeFailure(
                        "UnencodableOutput",
                        "Capability output does not match its declared schema"
                      )
                    )
                  ),
              })
            ),
        })
      );
    };

    return invoke;
  });

export const toExecuteCapability = <
  const Caps extends readonly [AnyCapability, ...AnyCapability[]],
>(
  capabilities: Caps,
  options?: ExecuteOptions
) => {
  const limits = resolveLimits(options ?? {});

  const catalog = toCatalog(capabilities);
  const declarations = toTypeScript(catalog);

  const discovery = discoverCatalog(
    catalog,
    options?.catalogBudget ??
      Match.value(options?.declarations).pipe(
        Match.when("inline", () => Number.MAX_SAFE_INTEGER),
        Match.when("search", () => 0),
        Match.orElse(() => 2000)
      )
  );

  const discoverySearch = implement(
    defineContract("$codemode.search", {
      description: "Search available code-mode capability signatures",
      failure: Schema.Never,
      input: SearchInput,
      output: SearchResult,
    }),
    ({ limit, offset, query }) =>
      searchPage(catalog, query, limit ?? 5, offset ?? 0)
  );

  const hasApproval = capabilities.some((item) => item.contract.needsApproval);
  // SAFETY: Caps preserves the literal approval flag for the generated capability, and `some` over the same array computes exactly that flag.
  // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- some over the same array computes the literal approval flag Caps carries.
  const needsApproval = hasApproval as NeedsApprovalOf<Caps>;

  const executeContract = defineContract("execute", {
    annotations: {
      destructive: capabilities.some(
        (item) => item.contract.annotations.destructive
      ),
      openWorld: capabilities.some(
        (item) => item.contract.annotations.openWorld
      ),
      readOnly: capabilities.every(
        (item) => item.contract.annotations.readOnly
      ),
    },
    description: executeDescription(discovery),
    failure: ExecuteFailure,
    input: ExecuteInput,
    needsApproval,
    output: ExecuteResult,
  });

  const capability = implement(
    executeContract,
    Effect.fn("CodeMode.execute")(function* execute({ code }) {
      const runtime = import("./sandbox-result.js");

      const { sandboxRunner } = yield* Effect.promise(
        runtime.finally.bind(runtime, undefined)
      );

      const invoke = yield* invokerFor([...capabilities, discoverySearch]);

      const sandbox = yield* Sandbox;

      const run = yield* sandboxRunner(sandbox.run, limits)(
        code,
        invoke,
        catalog.capabilities.map((entry) => entry.name)
      );

      if (run.diagnostic !== null && run.diagnostic !== undefined) {
        return yield* new ExecuteError({
          ...run.diagnostic,
          logs: run.logs,
          toolCalls: run.toolCalls ?? [],
          truncated: run.truncated ?? false,
        });
      }

      return {
        logs: run.logs,
        // SAFETY: every Sandbox implementation must JSON-round-trip a successful result before crossing this boundary.
        // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- every Sandbox JSON-round-trips a successful result before this boundary.
        result: run.result as typeof ExecuteResult.Type.result,
        toolCalls: run.toolCalls ?? [],
        truncated: run.truncated ?? false,
      };
    })
  );

  return { capability, catalog, declarations } as const;
};

export const toCodeMode = <
  const Caps extends readonly [AnyCapability, ...AnyCapability[]],
>(
  capabilities: Caps,
  options?: CodeModeOptions
): CodeModeProjection<Caps> => {
  const executeProjection = toExecuteCapability(capabilities, options);
  const { catalog, declarations } = executeProjection;
  const searchLimit = options?.searchLimit ?? 5;

  const execute = Tool.make("execute", {
    description: executeProjection.capability.contract.description,
    failure: failureSchemaOf(executeProjection.capability.contract),
    needsApproval: executeProjection.capability.contract.needsApproval,
    parameters: ExecuteInput,
    success: ExecuteResult,
  })
    .annotate(
      Tool.Readonly,
      capabilities.every(
        (capability) => capability.contract.annotations.readOnly
      )
    )
    .annotate(
      Tool.Destructive,
      capabilities.some(
        (capability) => capability.contract.annotations.destructive
      )
    )
    .annotate(
      Tool.OpenWorld,
      capabilities.some(
        (capability) => capability.contract.annotations.openWorld
      )
    );

  const toolkit = Toolkit.make(search, execute);

  const layer = toolkit.toLayer(
    Effect.gen(function* buildCodeModeHandlers() {
      const context = yield* Effect.context<
        RequirementsOf<Caps> | ApprovalRequirement<NeedsApprovalOf<Caps>>
      >();

      const sandbox = yield* Sandbox;

      return toolkit.of({
        execute: (input) =>
          executeProjection.capability
            .handler(input)
            .pipe(
              Effect.provideService(Sandbox, sandbox),
              Effect.provideContext(context)
            ),
        search: ({ limit, offset, query }) =>
          searchPage(catalog, query, limit ?? searchLimit, offset ?? 0),
      });
    })
  );

  return { catalog, declarations, layer, toolkit };
};

// @effect-diagnostics anyUnknownInErrorContext:off unsafeEffectTypeAssertion:off missingEffectContext:off -- This projection erases each capability's schema and requirement types while building the heterogeneous RpcGroup and recovers them at its public boundary.
import type { Layer } from "effect";
import { Effect } from "effect";
import type * as Rpc from "effect/rpc/Rpc";
import type * as RpcGroup from "effect/rpc/RpcGroup";

import type { AnyCapability, ContractOf, RequirementsOf } from "./contract.js";
import { toRpcGroup } from "./to-rpc-group.js";
import type { RpcsOf } from "./to-rpc-group.js";

export type ContractsOf<Caps extends readonly AnyCapability[]> = {
  readonly [K in keyof Caps]: ContractOf<Caps[K]>;
};

export interface RpcProjection<Caps extends readonly AnyCapability[]> {
  readonly group: RpcGroup.RpcGroup<RpcsOf<ContractsOf<Caps>>[number]>;
  readonly layer: Layer.Layer<
    Rpc.ToHandler<RpcsOf<ContractsOf<Caps>>[number]>,
    never,
    RequirementsOf<Caps>
  >;
}

export const toRpc = <const Caps extends readonly AnyCapability[]>(
  capabilities: Caps
): RpcProjection<Caps> => {
  const contracts = capabilities.map((capability) => capability.contract);
  // SAFETY: mapping preserves the capability order and each implementation exposes its exact contract.
  // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- projection boundary: map keeps capability order, so the array is ContractsOf<Caps>.
  const contractTuple = contracts as ContractsOf<Caps>;
  const { group } = toRpcGroup(contractTuple);

  const built = group.toLayer(
    Effect.gen(function* buildHandlers() {
      const context = yield* Effect.context<RequirementsOf<Caps>>();

      const handlers: Record<
        string,
        (
          // oxlint-disable-next-line anti-slop/no-unknown-parameters -- RpcGroup invokes this only after decoding the RPC payload schema.
          payload: unknown
        ) => Effect.Effect<unknown, unknown>
      > = {};

      for (const capability of capabilities) {
        // SAFETY: the server decodes this RPC's payload schema before dispatch, and the capability's requirements are included in RequirementsOf<Caps>.
        // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- projection boundary erases the handler type; RequirementsOf<Caps> restores it.
        const run = capability.handler as (
          // oxlint-disable-next-line anti-slop/no-unknown-parameters -- RpcGroup invokes this only after decoding the RPC payload schema.
          input: unknown
        ) => Effect.Effect<unknown, unknown, RequirementsOf<Caps>>;

        handlers[capability.contract.name] = (payload) =>
          run(payload).pipe(Effect.provideContext(context));
      }

      // SAFETY: the loop uses each capability contract's exact name, and its handler dispatches through that contract's schema-backed RPC definition.
      // oxlint-disable-next-line typescript/no-unsafe-type-assertion, anti-slop/no-chained-type-assertions -- This heterogeneous projection recovers the mapped handlers after the runtime name-indexed loop.
      return handlers as unknown as RpcGroup.HandlersFrom<
        RpcsOf<ContractsOf<Caps>>[number]
      >;
    })
  );

  // SAFETY: the group contains exactly the RPCs derived from the capability contracts, and the handlers capture but do not provide their requirements.
  // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- projection boundary: the group holds exactly the RPCs derived from the contracts.
  const layer = built as RpcProjection<Caps>["layer"];

  return { group, layer };
};

import { expect, it } from "@effect/vitest";
import { Deferred, Effect, Ref, Schema } from "effect";
import * as Arbitrary from "effect/Arbitrary";

import { boundedTraversal } from "./fixtures/wiki/bounded-traversal.js";

const Traversal = Schema.Struct({
  concurrency: Schema.Literals([1, 2, 3, 4]),
  count: Schema.Literals([1, 2, 3, 4, 5, 6, 7, 8]),
});

it.effect.prop(
  "traversal never exceeds its supplied bound and preserves input order",
  { scenario: Arbitrary.schema(Traversal) },
  ({ scenario }) =>
    Effect.gen(function* traversalBound() {
      const observed = yield* boundedTraversal(scenario);
      expect(observed.maximum).toBeGreaterThan(0);
      expect(observed.maximum).toBeLessThanOrEqual(scenario.concurrency);
      expect(observed.active).toBe(0);
      expect(observed.results).toEqual(
        Array.from({ length: scenario.count }, (_, index) => index)
      );
    })
);

it.effect(
  "closing the owner interrupts scoped child work before returning",
  () =>
    Effect.gen(function* childOwnership() {
      const started = yield* Deferred.make<boolean>();
      const interrupted = yield* Ref.make(0);
      yield* Effect.scoped(
        Effect.gen(function* ownChild() {
          yield* Deferred.succeed(started, true).pipe(
            Effect.andThen(Effect.never),
            Effect.onInterrupt(() =>
              Ref.update(interrupted, (count) => count + 1)
            ),
            Effect.forkScoped
          );
          yield* Deferred.await(started);
        })
      );
      expect(yield* Ref.get(interrupted)).toBe(1);
    })
);

import { Effect, Ref } from "effect";

export const boundedTraversal = Effect.fnUntraced(
  function* boundedTraversal(options: {
    readonly concurrency: number;
    readonly count: number;
  }) {
    const activity = yield* Ref.make({ active: 0, maximum: 0 });
    const input = Array.from({ length: options.count }, (_, index) => index);

    const results = yield* Effect.forEach(
      input,
      (index) =>
        Effect.acquireUseRelease(
          Ref.update(activity, (state) => ({
            active: state.active + 1,
            maximum: Math.max(state.maximum, state.active + 1),
          })),
          () => Effect.yieldNow.pipe(Effect.andThen(Effect.succeed(index))),
          () =>
            Ref.update(activity, (state) => ({
              ...state,
              active: state.active - 1,
            }))
        ),
      { concurrency: options.concurrency }
    );

    return { ...(yield* Ref.get(activity)), results };
  }
);

import { Effect, ManagedRuntime } from "effect";
import type { Ref } from "effect";

import { BoundaryResource } from "./boundary-resource.js";

export const makeForeignRuntimeBoundary = (options: {
  readonly acquired: Ref.Ref<number>;
  readonly released: Ref.Ref<number>;
}) => {
  const runtime = ManagedRuntime.make(BoundaryResource.layer(options));

  const read = Effect.gen(function* readBoundaryResource() {
    const resource = yield* BoundaryResource;

    return yield* resource.read;
  });

  return {
    close: runtime.dispose.bind(runtime),
    read: () => runtime.runPromise(read),
  };
};

import { expect, it } from "@effect/vitest";
import { Effect, Ref, Result } from "effect";

import { makeForeignRuntimeBoundary } from "./fixtures/wiki/foreign-runtime-boundary.js";

it.effect(
  "a foreign boundary builds once, closes once, and refuses reuse",
  () =>
    Effect.gen(function* runtimeLifetime() {
      const acquired = yield* Ref.make(0);
      const released = yield* Ref.make(0);
      yield* Effect.acquireUseRelease(
