export const contentVersionRetryDefaults = {
  deadlineMs: 120_000,
  initialDelayMs: 1000,
  maximumDelayMs: 10_000,
};

export const settledContentVersionCheck = Effect.fn(
  "settledContentVersionCheck"
)(function* settledContentVersionCheck<E, R>(
  work: Effect.Effect<Verdict, E, R>,
  options = contentVersionRetryDefaults
) {
  const { attempts, elapsedMs } = yield* runPoll(
    (remainingMs) =>
      runCheck(
        "content-version",
        work.pipe(Effect.timeout(Math.max(1, remainingMs)))
      ).pipe(
        Effect.map((verdict) => ({
          observation: verdict,
          settled:
            gateOutcome(verdict) === "pass" ||
            verdict.reason !== "content-version-mismatch",
        }))
      ),
    options
  );

  const rows = attempts.map((row) => row.observation);
  const verdict = rows.at(-1);

  if (verdict === undefined) {
    return yield* Effect.die("content-version-poll-without-attempt");
  }

  return {
    ...verdict,
    counts: {
      ...verdict.counts,
      attempts: rows.length,
      deadlineMs: options.deadlineMs,
      durationMs: elapsedMs,
      failedAttempts: rows.filter((row) => gateOutcome(row) !== "pass").length,
    },
    provenance: rows.flatMap((row, index) => [
      {
        fetchedAt: row.observedAt,
        id: `content-attempt:${index + 1}`,
        source: "content-version-check",
        status: `${row.status}:${row.reason}`,
      },
      ...(row.provenance ?? []),
    ]),
  } satisfies Verdict;
});

export const postDeployChecks = Effect.fn("postDeployChecks")(
  function* postDeployChecks(
    base: string,
    contentGeneration: string,
    appliedAt: number,
    contentRetry?: typeof contentVersionRetryDefaults
  ) {
    const retry = contentRetry ?? {
      ...contentVersionRetryDefaults,
      deadlineMs: yield* Config.Int("DEPLOY_CONTENT_VERSION_DEADLINE_MS").pipe(
        Config.withDefault(contentVersionRetryDefaults.deadlineMs)
      ),
    };

    yield* Schema.decodeEffect(
      Schema.Int.check(Schema.isBetween({ maximum: 600_000, minimum: 0 }))
    )(retry.deadlineMs);

    const client = yield* HttpClient.HttpClient;
    const url = base.replace(/\/$/u, "");

    const verdicts: Verdict[] = [
      yield* settledContentVersionCheck(
        contentVersionCheck(url, "/", contentGeneration),
        retry
      ),
      yield* settledContentVersionCheck(
        contentVersionCheck(url, "/index.md", contentGeneration),
        retry
      ),
      yield* settledContentVersionCheck(
        htmlContentVersionCheck(url, "/", contentGeneration),
        retry
      ),
      yield* settledContentVersionCheck(
        htmlContentVersionCheck(url, "/news", contentGeneration),
        retry
      ),
    ];

    for (const route of [
      "/",
      "/llms.txt",
      "/openapi.json",
      "/.well-known/mcp.json",
      "/.well-known/agent-skills/index.json",
    ]) {
      verdicts.push(
        yield* measuredCheck(
          `route:${route}`,
          client
            .get(`${url}${route}`)
            .pipe(Effect.map((response) => response.status === 200))
        )
      );
    }

    for (const accept of ["text/html", "text/markdown"]) {
      verdicts.push(
        yield* measuredCheck(
          `tokenmaxx-indexable:${accept}`,
          Effect.gen(function* workshopIndexability() {
            const response = yield* client.get(`${url}/tokenmaxx`, {
              headers: { accept },
            });

            const body = yield* response.text;

            return (
              response.status === 200 &&
              response.headers["x-robots-tag"]?.includes("noindex") !== true &&
              !body.includes('<meta name="robots" content="noindex"') &&
              (accept === "text/html" ||
                response.headers["cache-control"]?.includes("no-store") ===
                  true)
            );
          })
        )
      );
    }

    for (const route of ["/news", "/directory", "/llms.txt"]) {
      verdicts.push(
        yield* measuredCheck(
          `cafe-submission-guide:${route}`,
          Effect.gen(function* cafeSubmissionGuideCheck() {
            const response = yield* client.get(`${url}${route}`, {
              headers: { accept: "text/markdown" },
            });

            const text = yield* response.text;

            return (
              response.status === 200 &&
              text.includes("cafe-news.yml") &&
              text.includes("cafe-project.yml") &&
              text.includes(
                "File only after the person approves that exact issue."
              ) &&
              text.includes("Listing is not guaranteed.")
            );
          })
        )
      );
    }

    verdicts.push(
      yield* measuredCheck(
        "tokenmaxx-sitemap",
        Effect.gen(function* workshopSitemap() {
          const response = yield* client.get(`${url}/sitemap.xml`);
          const body = yield* response.text;

          return (
            response.status === 200 &&
            body.includes(`<loc>${url}/tokenmaxx</loc>`) &&
            !body.includes(`<loc>${url}/tokenmaxx/`)
          );
        })
      ),
      yield* measuredCheck(
        "markdown-canonicals",
        Effect.gen(function* markdownCanonicals() {
          const matches = yield* Effect.forEach(
            ["/AGENTS.md", "/README.md", "/VISION.md", "/log.md"],
            (route) =>
              client
                .get(`${url}${route}`)
                .pipe(
                  Effect.map(
                    (response) =>
                      response.status === 200 &&
                      response.headers.link?.includes(
                        `<${url}${route === "/log.md" ? "/log" : route}>; rel="canonical"`
                      ) === true
                  )
                )
          );

          return matches.every(Boolean);
        })
      )
    );

    for (const route of [
      "/tokenmaxx/confirm?token=invalid",
      "/tokenmaxx/unsubscribe?token=invalid",
      "/tokenmaxx/interest",
      "/tokenmaxx/four-comma-club.jpg",
    ]) {
      verdicts.push(
        yield* measuredCheck(
          `tokenmaxx-noindex:${route}`,
          client
            .get(`${url}${route}`)
            .pipe(
              Effect.map(
                (response) =>
                  response.headers["x-robots-tag"]?.includes("noindex") === true
              )
            )
        )
      );
    }

    const post = (
      route: string,
      json: string,
      headers: Readonly<Record<string, string>> = {}
    ) =>
      client.execute(
        HttpClientRequest.post(`${url}${route}`).pipe(
          HttpClientRequest.setHeaders({
            "content-type": "application/json",
            ...headers,
          }),
          HttpClientRequest.bodyText(json, "application/json")
        )
      );

    const mcpHeaders = {
      "MCP-Protocol-Version": "2026-07-28",
      accept: "application/json, text/event-stream",
    };

    const meta = {
      "io.modelcontextprotocol/clientCapabilities": {},
      "io.modelcontextprotocol/clientInfo": {
        name: "rat-stack-checks",
        version: "0.1.0",
      },
      "io.modelcontextprotocol/protocolVersion": "2026-07-28",
    };

    verdicts.push(
      yield* measuredCheck(
        "mcp-tools-list",
        Effect.gen(function* toolsList() {
          const response = yield* post(
            "/mcp",
            JSON.stringify({
              id: "deploy-tools",
              jsonrpc: "2.0",
              method: "tools/list",
              params: { _meta: meta },
            }),
            { ...mcpHeaders, "Mcp-Method": "tools/list" }
          );

          const document =
            yield* HttpClientResponse.schemaBodyJson(ToolsResponse)(response);

          return (
            response.status === 200 &&
            ["search", "read", "execute"].every((name) =>
              document.result.tools.some((tool) => tool.name === name)
            )
          );
        })
      ),
      yield* measuredCheck(
        "execute-round-trip",
        Effect.gen(function* executeRoundTrip() {
          const response = yield* post(
            "/api/execute",
            JSON.stringify({
              code: 'const found = await tools.search({ query: "learn-rat-stack", limit: 1 }); return await tools.read({ id: found.matches[0].id });',
            })
          );

          const document =
            yield* HttpClientResponse.schemaBodyJson(ExecuteResponse)(response);

          return (
            response.status === 200 &&
            document.result.id === "ratstack://skills/learn-rat-stack" &&
            document.result.text.trim().length > 0
          );
        })
      ),
      yield* measuredCheck(
        "sandbox-network-refused",
        Effect.gen(function* networkRefused() {
          const response = yield* post(
            "/api/execute",
            JSON.stringify({
              code: 'return await fetch("https://example.com");',
            })
          );

          const document =
            yield* HttpClientResponse.schemaBodyJson(SandboxResponse)(response);

          return (
            response.status === 422 &&
            document.kind === "ExecutionFailure" &&
            document.message
              .toLowerCase()
              .includes("not permitted to access the internet")
          );
        })
      ),
      yield* measuredCheck(
        "sandbox-timeout",
        Effect.gen(function* sandboxTimeout() {
          const response = yield* post(
            "/api/execute",
            JSON.stringify({ code: "while(true){}" })
          );

          const document =
            yield* HttpClientResponse.schemaBodyJson(SandboxResponse)(response);

          return response.status === 422 && document.kind === "TimeoutExceeded";
        })
      ),
      yield* measuredCheck(
        "mcp-search",
        Effect.gen(function* mcpSearch() {
          const response = yield* post(
            "/mcp",
            JSON.stringify({
              id: "deploy-search",
              jsonrpc: "2.0",
              method: "tools/call",
              params: {
                _meta: meta,
                arguments: { limit: 1, query: "learn-rat-stack" },
                name: "search",
              },
            }),
            { ...mcpHeaders, "Mcp-Method": "tools/call", "Mcp-Name": "search" }
          );

          const document =
            yield* HttpClientResponse.schemaBodyJson(SearchResponse)(response);

          return (
            response.status === 200 &&
            document.result.structuredContent.matches.length > 0
          );
        })
      ),
      yield* rpcSearchCheck(url),
      yield* measuredCheck(
        "execute-429-document",
        Effect.gen(function* rateDocument() {
          const response = yield* client.get(`${url}/openapi.json`);

          const document =
            yield* HttpClientResponse.schemaBodyJson(RateDocument)(response);

          return (
            response.status === 200 &&
            Object.hasOwn(document.paths["/api/execute"].post.responses, "429")
          );
        })
      ),
      yield* settledReadinessCheck(
        Effect.gen(function* agentReadiness() {
          const response = yield* client.execute(
            HttpClientRequest.post("https://isitagentready.com/api/scan").pipe(
              HttpClientRequest.bodyText(
                JSON.stringify({ url }),
                "application/json"
              )
            )
          );

          const document =
            yield* HttpClientResponse.schemaBodyJson(ReadyResponse)(response);

          return { document, status: response.status };
        }),
        appliedAt
      )
    );

    return verdicts;
  },
  Effect.mapError(
    () =>
      new DeployStepError({
        keys: ["DEPLOY_CONTENT_VERSION_DEADLINE_MS"],
        reason: "content-version-retry-input-invalid",
        step: "checks",
      })
  ),
  Effect.scoped
);

import { Effect, Schema } from "effect";
import { HttpClient, HttpClientResponse } from "effect/http";

const Reply = Schema.Struct({ version: Schema.Int });

export class ResponseFixtureError extends Schema.TaggedError<
  ResponseFixtureError,
  { readonly brand: unique symbol }
>()("ResponseFixtureError", {
  cause: Schema.Defect(),
  phase: Schema.Literals(["status", "body"]),
}) {}

export const readValidatedResponse = Effect.fn("readValidatedResponse")(
  function* readValidatedResponse() {
    const client = (yield* HttpClient.HttpClient).pipe(
      HttpClient.filterStatusOk
    );

    const response = yield* client
      .get("https://provider.example.test/version")
      .pipe(
        Effect.mapError(
          (cause) => new ResponseFixtureError({ cause, phase: "status" })
        )
      );

    return yield* HttpClientResponse.schemaBodyJson(Reply)(response).pipe(
      Effect.mapError(
        (cause) => new ResponseFixtureError({ cause, phase: "body" })
      )
    );
  }
);

import { expect, it } from "@effect/vitest";
import { Effect, Result } from "effect";
import { HttpClient, HttpClientResponse } from "effect/http";

import { readValidatedResponse } from "./fixtures/validated-http-response.js";

it.effect.each([
  { body: '{"version":4}', expected: "success", status: 200 },
  { body: '{"version":4}', expected: "status", status: 503 },
  { body: "{", expected: "body", status: 200 },
  { body: '{"version":"four"}', expected: "body", status: 200 },
])("checks status and decoded shape: $expected ($status, $body)", (scenario) =>
  Effect.gen(function* validateResponse() {
    const client = HttpClient.make((request) =>
      Effect.sync(() =>
        HttpClientResponse.fromWeb(
          request,
          new Response(scenario.body, {
            headers: { "content-type": "application/json" },
            status: scenario.status,
          })
        )
      )
    );

    const result = yield* readValidatedResponse().pipe(
      Effect.provideService(HttpClient.HttpClient, client),
      Effect.result
    );

    if (Result.isFailure(result)) {
      expect(result.failure._tag).toBe("ResponseFixtureError");
      expect(result.failure.phase).toBe(scenario.expected);
    } else {
      expect(scenario.expected).toBe("success");
      expect(result.success.version).toBe(4);
    }
  })
);

import * as Cloudflare from "@alchemy.run/cloudflare";
import { basinStream, icebergSink } from "@rat-stack/basin";
import {
  EventSink,
  EventSinkError,
  RawEventSchema,
} from "@rat-stack/core/event-sink";
import "alchemy/Phase";
import { Random } from "alchemy/Random";
import { retain } from "alchemy/RemovalPolicy";
import * as RuntimeContext from "alchemy/RuntimeContext";
import { Stage } from "alchemy/Stage";
import { Effect, Layer, Redacted, Schema } from "effect";
import { identity } from "effect/Function";

import { VisitorSalt } from "./visitor-salt.js";

export interface BasinOptions {
  readonly id: string;
}

export const EVENTS_TABLE = "events_raw";

const encodeRawEvent = Schema.encodeEffect(RawEventSchema);

export const unstructuredRow = (event: typeof RawEventSchema.Type) =>
  encodeRawEvent(event).pipe(Effect.map((value) => ({ value })));

const retainInProd =
  globalThis.__ALCHEMY_RUNTIME__ === true
    ? identity
    : retain(Stage.pipe(Effect.map((stage) => stage === "prod")));

export const basinFoundation = ({ id }: BasinOptions) =>
  Effect.gen(function* declareBasinFoundation() {
    const { bucket, stream } = yield* basinStream(`${id}Events`);
    const salt = yield* Random(`${id}VisitorSalt`).pipe(retainInProd);

    return { bucket, salt, stream } as const;
  });

export const Basin = ({ id }: BasinOptions) =>
  Layer.unwrap(
    Effect.gen(function* buildBasinEvents() {
      const { bucket, salt, stream } = yield* basinFoundation({ id });

      if (globalThis.__ALCHEMY_RUNTIME__ !== true) {
        yield* icebergSink({
          bucketName: bucket.bucketName,
          name: `${id}Events`,
          streamName: stream.name,
          table: EVENTS_TABLE,
        });
      }

      const saltValue = yield* salt.text;
      const writer = yield* Cloudflare.Pipelines.WriteStream(stream);

      return Layer.mergeAll(
        Layer.succeed(EventSink, {
          send: (events) =>
            Effect.forEach((event: (typeof events)[number]) =>
              unstructuredRow(event)
            )(events).pipe(
              Effect.flatMap((records) => writer.send(records)),
              Effect.mapError((cause) => new EventSinkError({ cause })),
              Effect.provide(RuntimeContext.RuntimeContext.phantom)
            ),
        }),
        Layer.succeed(VisitorSalt, {
          salt: saltValue.pipe(Effect.map((secret) => Redacted.value(secret))),
        })
      );
    })
  ).pipe(Layer.provide(Cloudflare.Pipelines.WriteStreamBinding));

import { Record, Schema } from "effect";
import { Dom, Subscription } from "foldkit";
import { defineMessageUnion } from "foldkit/message";

import { isEasingSpec } from "./easing.pure.js";
import * as SpringMotion from "./spring.pure.js";
import type { Spring, SpringConfig } from "./spring.pure.js";
import * as TweenMotion from "./tween.pure.js";
import type { Tween, TweenOptions } from "./tween.pure.js";

export const REDUCED_MOTION_QUERY = "(prefers-reduced-motion: reduce)";

const conforms =
  <Value>() =>
  <Codec extends Schema.Schema<Value>>(codec: Codec) =>
    codec;

export const EasingSpecSchema = Schema.String.pipe(
  Schema.refine(isEasingSpec, {
    description:
      "An easing name, cubic-bezier(x1, y1, x2, y2), or steps(count, position)",
  })
);

export const TweenSchema = conforms<Tween>()(
  Schema.Struct({
    duration: Schema.Finite,
    easing: EasingSpecSchema,
    from: Schema.Finite,
    kind: Schema.Literal("tween"),
    startedAt: Schema.Finite,
    to: Schema.Finite,
  })
);

export const SpringConfigSchema = conforms<SpringConfig>()(
  Schema.Struct({
    damping: Schema.Finite,
    mass: Schema.Finite,
    restDelta: Schema.Finite,
    restSpeed: Schema.Finite,
    stiffness: Schema.Finite,
  })
);

export const SpringSchema = conforms<Spring>()(
  Schema.Struct({
    config: SpringConfigSchema,
    kind: Schema.Literal("spring"),
    position: Schema.Array(Schema.Finite),
    remainder: Schema.Finite,
    settled: Schema.Boolean,
    target: Schema.Array(Schema.Finite),
    velocity: Schema.Array(Schema.Finite),
  })
);

export const Clock = Schema.Struct({
  now: Schema.Finite,
  reducedMotion: Schema.Boolean,
});

export type MotionClock = typeof Clock.Type;

export const initialClock: MotionClock = { now: 0, reducedMotion: false };

export const Message = defineMessageUnion({
  ChangedReducedMotion: { isReducedMotion: Schema.Boolean },
  TickedFrame: { elapsed: Schema.Finite },
});

export type MotionMessage = typeof Message.Type;

export interface Motion<
  TweenKey extends string = string,
  SpringKey extends string = string,
> {
  readonly clock: MotionClock;
  readonly tweens: Readonly<Record<TweenKey, Tween>>;
  readonly springs: Readonly<Record<SpringKey, Spring>>;
}

export interface MotionKeys<TweenKey extends string, SpringKey extends string> {
  readonly tweens: readonly TweenKey[];
  readonly springs: readonly SpringKey[];
}

export const motionSchema = <
  const TweenKey extends string,
  const SpringKey extends string,
>(
  keys: MotionKeys<TweenKey, SpringKey>
) =>
  Schema.Struct({
    clock: Clock,
    springs: Schema.Record(Schema.Literals(keys.springs), SpringSchema),
    tweens: Schema.Record(Schema.Literals(keys.tweens), TweenSchema),
  });

export const isAnimating = <TweenKey extends string, SpringKey extends string>(
  motion: Motion<TweenKey, SpringKey>
) =>
  Object.values<Tween>(motion.tweens).some(
    (animation) => !TweenMotion.isDone(animation, motion.clock.now)
  ) ||
  Object.values<Spring>(motion.springs).some(
    (animation) => !SpringMotion.isSettled(animation)
  );

const settleAll = <TweenKey extends string, SpringKey extends string>(
  motion: Motion<TweenKey, SpringKey>
): Motion<TweenKey, SpringKey> => ({
  clock: motion.clock,
