    : node.imported.value;

interface ImportIdentity {
  readonly module: string;
  readonly name: string | null;
}

const importBindingIdentity = (
  definition: Definition
): ImportIdentity | null => {
  const { parent } = definition.node;

  if (
    definition.type !== "ImportBinding" ||
    parent?.type !== "ImportDeclaration"
  ) {
    return null;
  }

  const module = stringValue(parent.source);

  if (module === null) {
    return null;
  }

  return {
    module,
    name:
      definition.node.type === "ImportSpecifier"
        ? importedName(definition.node)
        : null,
  };
};

const importIdentity = (
  expression: ESTree.Expression,
  scope: Scope | null,
  context: RuleContext,
  seen = new Set<Definition["node"]>()
): ImportIdentity | null => {
  const requireFunction = (
    candidate: ESTree.Expression,
    candidateScope: Scope | null,
    visited = new Set<Definition["node"]>()
  ): boolean => {
    const requireBinding = (name: string, bindingScope: Scope | null) => {
      const variable = variableOf(name, bindingScope);

      if (variable === undefined) {
        return name === "require";
      }

      const [definition] = variable.defs;

      if (
        definition?.type !== "Variable" ||
        definition.node.type !== "VariableDeclarator" ||
        definition.node.init === null ||
        !isStableVariable(variable) ||
        visited.has(definition.node)
      ) {
        return false;
      }

      visited.add(definition.node);

      const declarationScope = context.sourceCode.getScope(definition.node);

      if (definition.node.id.type === "ObjectPattern") {
        const initializer = unwrapExpression(definition.node.init);

        return (
          initializer.type === "Identifier" &&
          initializer.name === "module" &&
          variableOf("module", declarationScope) === undefined &&
          definition.node.id.properties.some(
            (property) =>
              property.type === "Property" &&
              property.value.type === "Identifier" &&
              property.value.name === name &&
              staticPropertyKeyName(property) === "require"
          )
        );
      }

      if (definition.node.id.type !== "Identifier") {
        return false;
      }

      return requireFunction(definition.node.init, declarationScope, visited);
    };

    const target = unwrapExpression(candidate);

    if (target.type === "Identifier") {
      return requireBinding(target.name, candidateScope);
    }

    if (target.type === "MemberExpression") {
      return (
        staticPropertyName(target) === "require" &&
        target.object.type === "Identifier" &&
        target.object.name === "module" &&
        variableOf("module", candidateScope) === undefined
      );
    }

    if (target.type === "CallExpression") {
      const identity = importIdentity(
        target.callee,
        candidateScope,
        context,
        visited
      );

      return (
        identity?.name === "createRequire" &&
        (identity.module === "module" || identity.module === "node:module")
      );
    }

    return false;
  };

  const loadedModuleIdentity = (
    candidate: ESTree.Expression,
    candidateScope: Scope | null
  ): ImportIdentity | null => {
    const target = unwrapExpression(candidate);

    if (target.type === "AwaitExpression") {
      return loadedModuleIdentity(target.argument, candidateScope);
    }

    if (target.type === "ImportExpression") {
      const module = stringValue(target.source);

      return module === null ? null : { module, name: null };
    }

    if (target.type !== "CallExpression") {
      return null;
    }

    const [argument] = target.arguments;

    if (
      argument === undefined ||
      argument.type === "SpreadElement" ||
      !requireFunction(target.callee, candidateScope)
    ) {
      return null;
    }

    const module = stringValue(argument);

    return module === null ? null : { module, name: null };
  };

  const importIdentityForPattern = (
    name: string,
    pattern: ESTree.ObjectPattern,
    initializer: ESTree.Expression,
    patternScope: Scope | null
  ): ImportIdentity | null => {
    const property = pattern.properties.find(
      (item) =>
        item.type === "Property" &&
        item.value.type === "Identifier" &&
        item.value.name === name
    );

    if (property?.type !== "Property") {
      return null;
    }

    const imported = staticPropertyKeyName(property);
    const namespace = importIdentity(initializer, patternScope, context, seen);

    if (
      namespace === null ||
      (namespace.name !== null && namespace.name !== "Effect") ||
      imported === null
    ) {
      return null;
    }

    return {
      module:
        namespace.name === null
          ? namespace.module
          : `${namespace.module}/${namespace.name}`,
      name: imported,
    };
  };

  const importIdentityForVariable = (
    name: string,
    variable: Variable
  ): ImportIdentity | null => {
    const [definition] = variable.defs;

    if (definition === undefined || seen.has(definition.node)) {
      return null;
    }

    seen.add(definition.node);

    const imported = importBindingIdentity(definition);

    if (imported !== null) {
      return imported;
    }

    if (
      definition.type !== "Variable" ||
      definition.node.type !== "VariableDeclarator" ||
      !isStableVariable(variable) ||
      definition.node.init === null
    ) {
      return null;
    }

    const initializer = definition.node.init;
    const declarationScope = context.sourceCode.getScope(definition.node);

    if (definition.node.id.type === "ObjectPattern") {
      return importIdentityForPattern(
        name,
        definition.node.id,
        initializer,
        declarationScope
      );
    }

    return importIdentity(initializer, declarationScope, context, seen);
  };

  const loadedModule = loadedModuleIdentity(expression, scope);

  if (loadedModule !== null) {
    return loadedModule;
  }

  const value = unwrapExpression(expression);

  if (value.type === "Identifier") {
    const variable = variableOf(value.name, scope);

    return variable === undefined
      ? null
      : importIdentityForVariable(value.name, variable);
  }

  if (value.type === "MemberExpression") {
    const object = importIdentity(value.object, scope, context, seen);
    const name = staticPropertyName(value);

    if (
      object === null ||
      (object.name !== null && object.name !== "Effect") ||
      name === null
    ) {
      return null;
    }

    return { module: object.module, name };
  }

  return null;
};

const isEffectCall = (
  node: ESTree.Node,
  member: string,
  context: RuleContext
) => {
  const expression = node.type === "CallExpression" ? node : null;

  if (expression === null) {
    return false;
  }

  const callee = unwrapExpression(expression.callee);
  const scope = context.sourceCode.getScope(expression);

  if (callee.type === "Identifier") {
    const identity = importIdentity(callee, scope, context);

    return (
      identity !== null &&
      (identity.module === "effect" || identity.module.startsWith("effect/")) &&
      identity.name === member
    );
  }

  if (
    callee.type !== "MemberExpression" ||
    staticPropertyName(callee) !== member
  ) {
    return false;
  }

  const identity = importIdentity(callee.object, scope, context);

  return (
    identity !== null &&
    (identity.module === "effect" || identity.module.startsWith("effect/")) &&
    (identity.name === "Effect" || identity.name === null)
  );
};

const cacheConstructors = [
  "cached",
  "cachedWithTTL",
  "cachedInvalidateWithTTL",
];

const isAlchemyModule = (module: string) =>
  module.startsWith("alchemy") || module.startsWith("@alchemy.run/");

const isInitializationCall = (
  node: ESTree.CallExpression,
  context: RuleContext
) => {
  const scope = context.sourceCode.getScope(node);
  const identity = importIdentity(node.callee, scope, context);

  if (identity !== null && isAlchemyModule(identity.module)) {
    return true;
  }

  if (node.callee.type !== "MemberExpression") {
    return false;
  }

  const object = importIdentity(node.callee.object, scope, context);

  return (
    object !== null &&
    ((object.module === "effect" && object.name === "Layer") ||
      object.module === "effect/Layer" ||
      isAlchemyModule(object.module))
  );
};

const isFetchFunction = (node: FunctionThunk) => {
  const { parent } = node;

  return (
    (node.type === "FunctionDeclaration" && node.id?.name === "fetch") ||
    (parent?.type === "VariableDeclarator" &&
      parent.id.type === "Identifier" &&
      parent.id.name === "fetch") ||
    (parent?.type === "Property" &&
      parent.key.type === "Identifier" &&
      parent.key.name === "fetch")
  );
};

const isEffectThunk = (node: FunctionThunk, context: RuleContext) => {
  const { parent } = node;

  return (
    parent?.type === "CallExpression" &&
    (isEffectCall(parent, "gen", context) ||
      (parent.callee.type === "CallExpression" &&
        isEffectCall(parent.callee, "fn", context)) ||
      isEffectCall(parent, "fnUntraced", context))
  );
};

const isEffectFnMethod = (node: FunctionThunk, context: RuleContext) => {
  const call = node.parent;

  return (
    call?.type === "CallExpression" &&
    call.parent?.type === "Property" &&
    call.parent.value === call &&
    (isEffectCall(call, "fn", context) ||
      isEffectCall(call, "fnUntraced", context) ||
      (call.callee.type === "CallExpression" &&
        isEffectCall(call.callee, "fn", context)))
  );
};

const isSharedConstruction = (node: ESTree.Node, context: RuleContext) => {
  let current: ESTree.Node | null = node.parent;

  while (current !== null) {
    if (
      current.type === "CallExpression" &&
      isInitializationCall(current, context)
    ) {
      return true;
    }

    if (
      (current.type === "FunctionDeclaration" ||
        current.type === "FunctionExpression" ||
        current.type === "ArrowFunctionExpression") &&
      isEffectFnMethod(current, context)
    ) {
      return false;
    }

    if (
      (current.type === "FunctionDeclaration" ||
        current.type === "FunctionExpression" ||
        current.type === "ArrowFunctionExpression") &&
      !isEffectThunk(current, context)
    ) {
      if (isFetchFunction(current)) {
        return false;
      }

      const scope = context.sourceCode.getScope(current);

      if (scope.upper?.type !== "module" && scope.upper?.type !== "global") {
        return false;
      }
    }

    current = current.parent;
  }

  return true;
};

const noSharedPendingCache = defineRule({
  create(context) {
    if (!isRuntimeSource(workspacePath(context.filename))) {
      return {};
    }

    return {
      CallExpression(node) {
        if (
          cacheConstructors.some((name) => isEffectCall(node, name, context)) &&
          isSharedConstruction(node, context)
        ) {
          context.report({ messageId: "pendingCache", node });
        }
      },
    };
  },
  meta: {
    docs: {
      description:
        "Keep pending request work out of shared initialization caches.",
    },
    messages: {
      pendingCache:
        "Effect.cached* at this scope shares pending work across requests. One request's interruption or failure then reaches every caller waiting on it. Fix: cache completed values only at module, service, or Worker initialization scope, or move the cache into the request; a scoped exception names its lifetime with `-- <reason>`.",
    },
    type: "problem",
  },
});

const isNodeWithin = (node: ESTree.Node, ancestor: ESTree.Node) => {
  let current: ESTree.Node | null = node;

  while (current !== null) {
    if (current === ancestor) {
      return true;
    }

    current = current.parent;
  }

  return false;
};

const isCapturedValue = (
  expression: ESTree.Expression,
  thunk: FunctionThunk,
  context: RuleContext,
  seen = new Set<Definition["node"]>()
): boolean => {
  const value = unwrapExpression(expression);

  if (value.type === "Identifier") {
    const definition = declarationOf(
      value.name,
      context.sourceCode.getScope(value)
    );

    if (definition === undefined) {
      return true;
    }

    if (seen.has(definition.node)) {
      return false;
    }

    seen.add(definition.node);

    if (!isNodeWithin(definition.node, thunk)) {
      return true;
    }

    if (definition.node.type === "VariableDeclarator") {
      return definition.node.init === null
        ? false
        : isCapturedValue(definition.node.init, thunk, context, seen);
    }

    const defaultedParameter = thunk.params.find(
      (parameter): parameter is AssignmentPatternNode =>
        parameter.type === "AssignmentPattern" &&
        parameter.left.type === "Identifier" &&
        parameter.left.name === value.name
    );

    return defaultedParameter === undefined
      ? false
      : isCapturedValue(defaultedParameter.right, thunk, context, seen);
  }

  if (value.type === "ThisExpression") {
    return true;
  }

  if (value.type === "MemberExpression") {
    if (value.object.type === "ThisExpression") {
      return true;
    }

    return isCapturedValue(value.object, thunk, context, seen);
  }

  return false;
};

const returnsCapturedHandle = (node: ESTree.Node, context: RuleContext) => {
  if (node.type !== "CallExpression") {
    return false;
  }

  const expression = unwrapExpression(node);

  if (
    expression.type !== "CallExpression" ||
    !isEffectCall(expression, "sync", context)
  ) {
    return false;
  }

  const [argument] = expression.arguments;

  const thunk =
    argument === undefined || argument.type === "SpreadElement"
      ? null
      : unwrapExpression(argument);

  if (
    thunk === null ||
    (thunk.type !== "ArrowFunctionExpression" &&
      thunk.type !== "FunctionExpression") ||
    thunk.body === null
  ) {
    return false;
  }

  if (thunk.body.type !== "BlockStatement") {
    return isCapturedValue(thunk.body, thunk, context);
  }

  const returns = thunk.body.body.filter(
    (statement): statement is ReturnStatementNode =>
      statement.type === "ReturnStatement"
  );

  const [returned] = returns;

  return (
    returns.length === 1 &&
    returned !== undefined &&
    returned.argument !== null &&
    isCapturedValue(returned.argument, thunk, context)
  );
};

const acquireReleaseConstructsInAcquireBody = defineRule({
  create(context) {
    return {
      CallExpression(node) {
        if (!isEffectCall(node, "acquireRelease", context)) {
          return;
        }

        const [acquire] = node.arguments;

        if (acquire === undefined || acquire.type === "SpreadElement") {
          return;
        }

        const expression = unwrapExpression(acquire);

        if (
          isEffectCall(expression, "succeed", context) ||
          returnsCapturedHandle(expression, context)
        ) {
          context.report({ messageId: "eagerAcquire", node: acquire });
        }
      },
    };
  },
  meta: {
    docs: {
      description:
        "Construct a resource inside the Effect.acquireRelease acquire Effect, not before it.",
    },
    messages: {
      eagerAcquire:
        "This acquire returns a resource built before acquire runs. An interruption in between leaks it, because release never sees it. Fix: build the resource inside acquire, for example `Effect.sync(() => new Pool(options))` or `Effect.tryPromise(...)`, not `Effect.succeed(handle)` or `Effect.sync(() => handle)`.",
    },
    type: "problem",
  },
});

const isModuleScopedVar = (node: ESTree.Node) => {
  let current = node.parent;

  while (current !== null && current.type !== "Program") {
    if (
      current.type === "ArrowFunctionExpression" ||
      current.type === "FunctionDeclaration" ||
      current.type === "FunctionExpression" ||
      current.type === "StaticBlock" ||
      current.type === "TSDeclareFunction" ||
      current.type === "TSModuleBlock"
    ) {
      return false;
    }

    current = current.parent;
  }

  return current?.type === "Program";
};

const noModuleLevelMutableState = defineRule({
  create(context) {
    if (!isRuntimeSource(workspacePath(context.filename))) {
      return {};
    }

    return {
      VariableDeclaration(node) {
        if (node.kind !== "let" && node.kind !== "var") {
          return;
        }

        const scope = context.sourceCode.getScope(node);

        const moduleScoped =
          node.kind === "let"
            ? scope.type === "module" || scope.type === "global"
            : isModuleScopedVar(node);

        if (moduleScoped) {
          context.report({ messageId: "moduleState", node });
        }
      },
    };
  },
  meta: {
    docs: {
      description: "Keep state out of module-level let and var bindings.",
    },
    messages: {
      moduleState:
        "Module-level let and var hold state that outlives one request. Every request a Worker isolate or server process handles shares it, so one request's state leaks into the next. Fix: keep the state in a `Ref` inside a Layer, a Durable Object, or the database.",
    },
    type: "problem",
  },
});

const waitingConstructors = new Map([
  ["Deferred", new Set(["make", "makeUnsafe"])],
  ["Cache", new Set(["make", "makeWith"])],
  ["Ref", new Set(["make", "makeUnsafe"])],
  ["Semaphore", new Set(["make", "makeUnsafe"])],
  ["Queue", new Set(["make", "bounded", "unbounded", "dropping", "sliding"])],
  ["Latch", new Set(["make", "makeUnsafe"])],
  ["PubSub", new Set(["make", "bounded", "unbounded", "dropping", "sliding"])],
  ["PartitionedSemaphore", new Set(["make", "makeUnsafe"])],
  ["TxSemaphore", new Set(["make"])],
]);

const isWaitingConstructor = (
  node: ESTree.CallExpression,
  context: RuleContext
) => {
  const scope = context.sourceCode.getScope(node);
  const callee = unwrapExpression(node.callee);
  const identity = importIdentity(callee, scope, context);

  if (identity?.module.startsWith("effect/") === true) {
    const primitive = identity.module.slice("effect/".length);

    return (
      waitingConstructors.get(primitive)?.has(identity.name ?? "") === true
    );
  }

  if (callee.type !== "MemberExpression") {
    return false;
  }

  const object = importIdentity(callee.object, scope, context);

  return (
    object?.module === "effect" &&
    waitingConstructors
      .get(object.name ?? "")
      ?.has(staticPropertyName(callee) ?? "") === true
  );
};

const isLayerOwnedConstruction = (
  node: ESTree.CallExpression,
  context: RuleContext
) => {
  const callee = unwrapExpression(node.callee);

  const constructorName =
    callee.type === "MemberExpression"
      ? staticPropertyName(callee)
      : importIdentity(callee, context.sourceCode.getScope(node), context)
          ?.name;

  if (constructorName === "makeUnsafe") {
    return false;
  }

  if (node.parent?.type !== "CallExpression") {
    return false;
  }

  const target = unwrapExpression(node.parent.callee);
  const scope = context.sourceCode.getScope(node.parent);
  const identity = importIdentity(target, scope, context);

  if (identity?.module === "effect/Layer") {
    return identity.name === "effect" || identity.name === "effectDiscard";
  }

  if (target.type !== "MemberExpression") {
    return false;
  }

  const owner = importIdentity(target.object, scope, context);

  return (
    (staticPropertyName(target) === "effect" ||
      staticPropertyName(target) === "effectDiscard") &&
    owner?.module === "effect" &&
    owner.name === "Layer"
  );
};

const isDurableObjectInstanceField = (
  field: ESTree.PropertyDefinition,
  context: RuleContext
) => {
  const owner = field.parent?.parent;

  const superclass =
    owner?.type === "ClassDeclaration" || owner?.type === "ClassExpression"
      ? owner.superClass
      : null;

  const identity =
    superclass === null
      ? null
      : importIdentity(superclass, context.sourceCode.getScope(field), context);

  return (
    !field.static &&
    identity?.module === "cloudflare:workers" &&
    identity.name === "DurableObject"
  );
};

const sharedWaiterOwner = (
  node: ESTree.Node,
  context: RuleContext
): ESTree.Node | null => {
  let current = node.parent;

  while (current !== null) {
    if (
      current.type === "ArrowFunctionExpression" ||
      current.type === "FunctionExpression" ||
      current.type === "FunctionDeclaration"
    ) {
      return null;
    }

    if (current.type === "PropertyDefinition") {
      return isDurableObjectInstanceField(current, context) ? null : current;
    }

    if (
      current.type === "VariableDeclarator" &&
      current.parent?.type === "VariableDeclaration" &&
      current.parent.kind === "const" &&
      isModuleScopedVar(current)
    ) {
      return current;
    }

    current = current.parent;
  }

  return null;
};

const sharedWaiters = defineRule({
  create(context) {
    if (!isRuntimeSource(workspacePath(context.filename))) {
      return {};
    }

    return {
      CallExpression(node) {
        if (
          sharedWaiterOwner(node, context) !== null &&
          isWaitingConstructor(node, context) &&
          !isLayerOwnedConstruction(node, context)
        ) {
          context.report({ messageId: "sharedWaiter", node });
        }
      },
    };
  },
  meta: {
    docs: {
      description:
        "Keep Deferred, Cache, Ref, Semaphore, Queue, Latch, PubSub, PartitionedSemaphore, and TxSemaphore construction out of module const bindings and class fields outside Durable Object instances. In drovr #2344 and #2348, cross-request waiters in a Worker isolate made another caller hang or receive a 503.",
    },
    messages: {
      sharedWaiter:
        "This waiting primitive lives at module level or outside a Durable Object instance. Worker request contexts then share its pending work, so another caller hangs or gets a 503. Fix: construct it inside a request-owned Effect or a Durable Object instance; for Layers use `Layer.effect(Tag, Ref.make(...))`, not `Layer.succeed(Tag, Ref.makeUnsafe(...))`, and never store it or its run result in a module const.",
    },
    type: "problem",
  },
});

const camelCase = (name: string) =>
  name
    .split(/[^A-Za-z0-9]+/u)
    .filter((part) => part !== "")
    .map((part, index) =>
      index === 0
        ? `${part.charAt(0).toLowerCase()}${part.slice(1)}`
        : `${part.charAt(0).toUpperCase()}${part.slice(1)}`
    )
    .join("");

const resolvesToName = (
  expression: ESTree.Expression,
  expected: string,
  scope: Scope | null,
  context: RuleContext
): boolean => {
  const identity = importIdentity(expression, scope, context);

  return (
    identity?.name === expected &&
    /^@[^/]+\/capability(?:\/contract)?$/u.test(identity.module)
  );
};

const contractName = (
  node: ESTree.Expression,
  scope: Scope | null,
  context: RuleContext
): string | null => {
  const expression = unwrapExpression(node);

  if (expression.type !== "CallExpression") {
    return null;
  }

  if (!resolvesToName(expression.callee, "defineContract", scope, context)) {
    return null;
  }

  const [first] = expression.arguments;

  return first === undefined || first.type === "SpreadElement"
    ? null
    : stringValue(first);
};

const contractBindingMatchesName = defineRule({
  create(context) {
    const check = (
      identifier: IdentifierNode,
      expression: ESTree.Expression
    ) => {
      const name = contractName(
        expression,
        context.sourceCode.getScope(identifier),
        context
      );

      if (name === null) {
        return;
      }

      const expected = camelCase(name);

      if (
        identifier.name !== expected &&
        identifier.name !== `${expected}Contract`
      ) {
        context.report({
          data: { expected, name },
          messageId: "binding",
          node: identifier,
        });
      }
    };

    return {
      AssignmentExpression(node) {
        if (node.left.type !== "Identifier") {
          return;
        }

        const definition = declarationOf(
          node.left.name,
          context.sourceCode.getScope(node.left)
        );

        if (
          definition?.type === "Variable" &&
          definition.node.type === "VariableDeclarator"
        ) {
          check(node.left, node.right);
        }
      },
      VariableDeclarator(node) {
        if (node.id.type === "Identifier" && node.init !== null) {
          check(node.id, node.init);
        }
      },
    };
  },
  meta: {
    docs: {
      description:
        "Name a defineContract binding after the contract, so a search for the name finds it.",
    },
    messages: {
      binding:
        'This binding does not match the contract name "{{name}}". Matching names keep imports, search, and the catalog lined up. Fix: rename it to `{{expected}}Contract` or `{{expected}}`.',
    },
    type: "suggestion",
  },
});

const isCapabilityWatcherModule = (module: string) =>
  /^@[^/]+\/capability(?:\/actor-watch)?$/u.test(module);

const callTarget = (node: ESTree.CallExpression) => {
  const callee = unwrapExpression(node.callee);

  if (callee.type !== "MemberExpression") {
    return { expression: callee, method: null };
  }

  const method = staticPropertyName(callee);

  return method === "call" || method === "apply"
    ? { expression: unwrapExpression(callee.object), method }
    : { expression: callee, method: null };
};

const callTargetIdentity = (
  node: ESTree.CallExpression,
  context: RuleContext
): ImportIdentity | null =>
  importIdentity(
    callTarget(node).expression,
    context.sourceCode.getScope(node),
    context
  );

const callArgument = (
  node: ESTree.CallExpression,
  index: number
): ESTree.Expression | null => {
  const { method } = callTarget(node);

  if (method === "call") {
    const argument = node.arguments[index + 1];

    return argument === undefined || argument.type === "SpreadElement"
      ? null
      : argument;
  }

  if (method === "apply") {
    const [, argumentList] = node.arguments;

    if (argumentList?.type !== "ArrayExpression") {
      return null;
    }

    const argument = argumentList.elements[index];

    return argument === null ||
      argument === undefined ||
      argument.type === "SpreadElement"
      ? null
      : argument;
  }

  const argument = node.arguments[index];

  return argument === undefined || argument.type === "SpreadElement"
    ? null
    : argument;
};

const isTransparentWrapper = (parent: ESTree.Node, child: ESTree.Node) => {
  if (parent.type === "AwaitExpression" || parent.type === "YieldExpression") {
    return parent.argument === child;
  }

  return (
    (parent.type === "ChainExpression" ||
      parent.type === "ParenthesizedExpression" ||
      parent.type === "TSAsExpression" ||
      parent.type === "TSNonNullExpression" ||
      parent.type === "TSSatisfiesExpression" ||
      parent.type === "TSTypeAssertion" ||
      parent.type === "TSInstantiationExpression") &&
    parent.expression === child
  );
};

const expressionForVariable = (
  node: ESTree.CallExpression,
  context: RuleContext
): ESTree.VariableDeclarator | null => {
  let current: ESTree.Node = node;
  let ancestor: ESTree.Node | null = current.parent;

  while (ancestor !== null) {
    if (isTransparentWrapper(ancestor, current)) {
      current = ancestor;
      ancestor = current.parent;
      continue;
    }

    if (ancestor.type === "VariableDeclarator" && ancestor.init === current) {
      return ancestor;
    }

    if (
      ancestor.type === "AssignmentExpression" &&
      ancestor.right === current &&
      ancestor.left.type === "Identifier"
    ) {
      const definition = declarationOf(
        ancestor.left.name,
        context.sourceCode.getScope(ancestor.left)
      );

      return definition?.node.type === "VariableDeclarator"
        ? definition.node
        : null;
    }

    return null;
  }

  return null;
};

const variableBinding = (
  identifier: IdentifierNode,
  context: RuleContext,
  seen = new Set<Definition["node"]>()
): ESTree.VariableDeclarator | null => {
  const variable = variableOf(
    identifier.name,
    context.sourceCode.getScope(identifier)
  );

  const definition = variable?.defs[0];

  if (
    definition?.type !== "Variable" ||
    definition.node.type !== "VariableDeclarator" ||
    seen.has(definition.node)
  ) {
    return null;
  }

  seen.add(definition.node);

  const initializer =
    definition.node.init === null
      ? null
      : unwrapExpression(definition.node.init);

  if (
    initializer?.type === "Identifier" &&
    variable !== undefined &&
    isStableVariable(variable)
  ) {
    return variableBinding(initializer, context, seen) ?? definition.node;
  }

  return definition.node;
};

const watchEffectActors = defineRule({
  create(context) {
    if (!isRuntimeSource(workspacePath(context.filename))) {
      return {};
    }

    const started: {
      readonly binding: ESTree.VariableDeclarator | null;
      readonly node: ESTree.CallExpression;
    }[] = [];

    const watchedBindings = new Set<ESTree.VariableDeclarator>();
    const watchedCalls = new Set<ESTree.CallExpression>();

    const bindingIsStable = (
      binding: ESTree.VariableDeclarator,
      actor: ESTree.CallExpression
    ) => {
      if (binding.id.type !== "Identifier") {
        return false;
      }

      const variable = variableOf(
        binding.id.name,
        context.sourceCode.getScope(binding)
      );

      return (
        variable !== undefined &&
        variable.references.every(
          (reference) =>
            !reference.isWrite() ||
            reference.init ||
            (reference.writeExpr !== null &&
              isNodeWithin(actor, reference.writeExpr))
        )
      );
    };

    return {
      CallExpression(node) {
        const identity = callTargetIdentity(node, context);

        if (
          identity?.module === "@xstate/effect" &&
          identity.name === "createEffectActor"
        ) {
          started.push({ binding: expressionForVariable(node, context), node });
        }

        if (
          identity === null ||
          !isCapabilityWatcherModule(identity.module) ||
          identity.name !== "watchActor"
        ) {
          return;
        }

        const argument = callArgument(node, 1);

        if (argument === null) {
          return;
        }

        const actor = unwrapExpression(argument);

        if (actor.type === "Identifier") {
          const binding = variableBinding(actor, context);

          if (binding !== null) {
            watchedBindings.add(binding);
          }

          return;
        }

        if (actor.type === "CallExpression") {
          watchedCalls.add(actor);
        }
      },
      "Program:exit"() {
        for (const actor of started) {
          const watched =
            actor.binding === null
              ? watchedCalls.has(actor.node)
              : watchedBindings.has(actor.binding) &&
                bindingIsStable(actor.binding, actor.node);

          if (!watched) {
            context.report({ messageId: "unwatched", node: actor.node });
          }
        }
      },
    };
  },
  meta: {
    docs: {
      description:
        "Hand every Effect-backed actor to watchActor so devtools can inspect it.",
    },
    messages: {
      unwatched:
        'This createEffectActor result is never passed to watchActor. Without it, rat_list_actors cannot see this machine. Fix: call `watchActor("<machine>", actor)` from `@rat-stack/capability/actor-watch` after `createEffectActor`; it is a no-op until devtools provides a watcher.',
    },
    type: "suggestion",
  },
});

const isLearnSnippet = (filename: string) =>
  /(?:^|\/)\.brain\/data\/learn-cards\/.+\.ts$/u.test(filename);

const primitiveServiceTypes = new Set([
  "TSAnyKeyword",
  "TSBigIntKeyword",
  "TSBooleanKeyword",
  "TSLiteralType",
  "TSNumberKeyword",
  "TSStringKeyword",
  "TSSymbolKeyword",
  "TSUnknownKeyword",
]);

const serviceDeclaration = (superClass: ESTree.Expression | null) => {
  if (superClass?.type !== "CallExpression") {
    return null;
  }

  const factory = superClass.callee;

  if (
    factory.type !== "CallExpression" ||
    factory.callee.type !== "MemberExpression" ||
    staticPropertyName(factory.callee) !== "Service"
  ) {
    return null;
  }

  const [key] = superClass.arguments;

  return {
    key: key === undefined || key.type === "SpreadElement" ? null : key,
    operations: factory.typeArguments?.params[1] ?? null,
  };
};

const staticLayerOf = (body: ESTree.ClassBody) =>
  body.body.find(
    (member) =>
      member.type === "PropertyDefinition" &&
      member.static &&
      member.key.type === "Identifier" &&
      member.key.name === "layer"
  );

const learnSnippetIdiom = defineRule({
  create(context) {
    if (!isLearnSnippet(workspacePath(context.filename))) {
      return {};
    }

    const checkService = (node: ESTree.Class) => {
      const service = serviceDeclaration(node.superClass);

      if (service === null) {
        return;
      }

      if (
        service.operations !== null &&
        primitiveServiceTypes.has(service.operations.type)
      ) {
        context.report({ messageId: "operations", node: service.operations });
      }

      const key = service.key === null ? null : stringValue(service.key);

      if (key === null || !key.includes("/")) {
        context.report({
          messageId: "namespacedKey",
          node: service.key ?? node,
        });
      }

      const layer = staticLayerOf(node.body);

      const className = node.id?.name;

      const usesOf =
        layer !== undefined &&
        className !== undefined &&
        context.sourceCode.getText(layer).includes(`${className}.of(`);

      if (!usesOf) {
        context.report({ messageId: "staticLayer", node: layer ?? node });
      }
    };

    return {
      CallExpression(node) {
        if (
          node.callee.type === "MemberExpression" &&
          staticPropertyName(node.callee)?.startsWith("provideService") === true
        ) {
          context.report({ messageId: "provideLayer", node });
        }
      },
      ClassDeclaration: checkService,
      ClassExpression: checkService,
    };
  },
  meta: {
    docs: {
      description:
        "Keep learn card snippets on the installed effect/AGENTS.md service idiom.",
    },
    messages: {
      namespacedKey:
        'This service key has no namespace. Two services with the same bare key share one identifier. Fix: give the service a namespaced key such as `"myapp/Greeter"`.',
      operations:
        "This service holds a primitive value instead of operations. A service is a set of effectful operations, and a primitive belongs in Config or a Context.Reference. Fix: shape the service as operations, for example `{ readonly greet: (name: string) => Effect.Effect<string> }`.",
      provideLayer:
        "This provides the service with provideService. A provideService call hides how the implementation is built. Fix: provide the service's static layer at the edge with `Effect.provide(Service.layer)`.",
      staticLayer:
        "This service has no static layer beside it. The implementation belongs beside the interface, where a reader finds both. Fix: attach `static readonly layer` to the service and build its value with `Service.of(...)`.",
    },
    type: "problem",
  },
});

const rawSourceNames = new Set([
  "frontmatter",
  "markdown",
  "rawText",
  "source",
  "sourceText",
  "svx",
]);

const isRawSourceIdentifier = (node: ESTree.Node) =>
  node.type === "Identifier" && rawSourceNames.has(node.name);

const auditedExpressions = new Set(
  auditedStringRegexes
    .filter((entry) => entry.reason !== "")
    .map((entry) => entry.expression)
);

const auditedContentRegex = defineRule({
  create(context) {
    const requireAudit = (node: ESTree.Node) => {
      const expression = context.sourceCode.getText(node);

      if (!auditedExpressions.has(expression)) {
        context.report({ data: { expression }, messageId: "unaudited", node });
      }
    };

    return {
      CallExpression(node) {
        const { callee } = node;

        if (
          callee.type !== "MemberExpression" ||
          callee.property.type !== "Identifier"
        ) {
          return;
        }

        const method = callee.property.name;

        const sourceArgument =
          (method === "exec" || method === "test") &&
          node.arguments.some(isRawSourceIdentifier);

        const sourceReceiver =
          (method === "match" ||
            method === "matchAll" ||
            method === "search") &&
          isRawSourceIdentifier(callee.object);

        if (sourceArgument || sourceReceiver) {
          context.report({ messageId: "sourceRegex", node });
        }
      },
      Literal(node) {
        if ("regex" in node && node.regex !== undefined) {
          requireAudit(node);
        }
      },
      NewExpression(node) {
        if (
          node.callee.type === "Identifier" &&
          node.callee.name === "RegExp"
        ) {
          requireAudit(node);
        }
      },
    };
  },
  meta: {
    docs: {
      description:
        "Keep regular expressions in the content pipeline to audited expressions over parsed values, never over svx source.",
    },
    messages: {
      sourceRegex:
        "A regular expression over raw svx source is forbidden. A regex over source breaks on the nesting, fences, and quoting the parser handles. Fix: parse the source with `apps/site/scripts/svx-ast.ts` and match parsed values instead.",
      unaudited:
        "Unaudited regular expression {{expression}}. Every content regex carries a recorded reason, so source matching stays reviewable. Fix: match a parsed value, or add the expression and its reason to `apps/site/scripts/source-regex-policy.ts`.",
    },
    type: "problem",
  },
});

const flagRemovalDate = defineRule({
  create(context) {
    return {
      CallExpression(node) {
        const identity = importIdentity(
          node.callee,
          context.sourceCode.getScope(node),
          context
        );

        const direct =
          node.callee.type === "Identifier" &&
          node.callee.name === "defineFlag";

        if (
          !direct &&
          !(
            identity?.name === "defineFlag" &&
            /^@rat-stack\/(?:core\/flags|flags)$/u.test(identity.module)
          )
        ) {
          return;
        }

        const options = node.arguments.at(2);

        const removal =
          options?.type === "ObjectExpression"
            ? options.properties.find(
                (property) =>
                  property.type === "Property" &&
                  staticPropertyKeyName(property) === "removeBy"
              )
            : undefined;

        const date =
          removal?.type === "Property" ? stringValue(removal.value) : null;

        if (date === null || !/^\d{4}-\d{2}-\d{2}$/u.test(date)) {
          context.report({ messageId: "removeBy", node });
        }
      },
    };
  },
  meta: {
    docs: {
      description:
        "Every feature flag declares its removal date at the call site.",
    },
    messages: {
      removeBy:
        'This defineFlag options object has no removeBy date literal. A flag without a removal date never gets cleaned up. Fix: add `removeBy: "YYYY-MM-DD"` as a string literal.',
    },
    type: "problem",
  },
});

const retainNeedsStagePolicy = defineRule({
  create(context) {
    return {
      CallExpression(node) {
        if (node.arguments.length !== 0) {
          return;
        }

        const identity = importIdentity(
          node.callee,
          context.sourceCode.getScope(node),
          context
        );

        if (
          identity?.name === "retain" &&
          (identity.module === "alchemy/RemovalPolicy" ||
            identity.module === "alchemy")
        ) {
          context.report({ messageId: "policy", node });
        }
      },
    };
  },
  meta: {
    docs: { description: "Resource retention needs an explicit stage policy." },
    messages: {
      policy:
        'This retain call has no stage policy. Unconditional retention leaves destroyed non-production stages orphaned. Fix: pass `Stage.pipe(Effect.map((stage) => stage === "prod"))`, or add a reasoned `rat-stack-patterns/retain-needs-stage-policy` disable directive for shared irreplaceable resources.',
    },
    type: "problem",
  },
});

const noSleepInLoop = defineRule({
  create(context) {
    if (!isRuntimeSource(workspacePath(context.filename))) {
      return {};
    }

    return {
      CallExpression(node) {
        if (!isEffectCall(node, "sleep", context)) {
          return;
        }

        let yielded = false;
        let parent: ESTree.Node | null = node;

        while (parent !== null) {
          if (
            parent.type === "FunctionExpression" ||
            parent.type === "FunctionDeclaration" ||
            parent.type === "ArrowFunctionExpression"
          ) {
            return;
          }

          if (parent.type === "YieldExpression") {
            yielded = true;
          }

          if (
            yielded &&
            (parent.type === "WhileStatement" ||
              parent.type === "DoWhileStatement" ||
              parent.type === "ForStatement" ||
              parent.type === "ForOfStatement" ||
              parent.type === "ForInStatement")
          ) {
            context.report({ messageId: "machine", node: parent });

            return;
          }

          ({ parent } = parent);
        }
      },
    };
  },
  meta: {
    docs: { description: "Sleeping retry loops belong in lifecycle machines." },
    messages: {
      machine:
        "This loop yields Effect.sleep. A hand-rolled retry or polling loop hides its states, cancellation, and resumption. Fix: move the loop into an XState lifecycle machine with declared `createEffectLogic` actors.",
    },
    type: "problem",
  },
});

export default definePlugin({
  meta: { name: "rat-stack-patterns" },
  rules: {
    "acquire-release-constructs-in-acquire-body":
      acquireReleaseConstructsInAcquireBody,
    "audited-content-regex": auditedContentRegex,
    "contract-binding-matches-name": contractBindingMatchesName,
    "flag-removal-date": flagRemovalDate,
    "learn-snippet-idiom": learnSnippetIdiom,
    "no-module-level-mutable-state": noModuleLevelMutableState,
    "no-shared-pending-cache": noSharedPendingCache,
    "no-sleep-in-loop": noSleepInLoop,
    "retain-needs-stage-policy": retainNeedsStagePolicy,
    "shared-waiters": sharedWaiters,
    "watch-effect-actors": watchEffectActors,
  },
});
